import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LAVA', color: string): HTMLCanvasElement {
        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LAVA') {
            // High-Performance Baked Liquid
            // 1. Fluid Body
            ctx.fillStyle = color;
            // Use a slightly irregular shape for base
            ctx.beginPath();
            for(let i=0; i<=12; i++) {
                const a = (i/12) * Math.PI * 2;
                // Static noise for shape
                const noise = Math.sin(a * 3) * 5; 
                const rad = r * 0.9 + noise;
                const x = Math.cos(a) * rad;
                const y = Math.sin(a) * rad;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // 2. Inner Depth (Crust/Darker Pool)
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = color; 
            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.65, 0, Math.PI * 2); 
            ctx.fill();

            // 3. Specular Highlights (Gloss)
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            ctx.beginPath();
            ctx.ellipse(0, -r * 0.55, r * 0.4, 6, 0, 0, Math.PI*2);
            ctx.fill();

            // 4. Baked Bubbles (Static)
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(r*0.3, r*0.3, r*0.08, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-r*0.25, -r*0.15, r*0.05, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    // OPTIMIZED: Replaced expensive procedural path generation with Cached Texture + Transform Animation
    // This reduces draw calls per hex from ~10 to 1, removing composite operation switches inside the loop.
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LAVA', color);
        const size = HEX_SIZE * 2.5; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate fluid motion via transforms instead of vertex recalculation
        // 1. Breathing Scale (Pulsing heat)
        const pulse = 1.0 + Math.sin(time * 2 + x * 0.1) * 0.05;
        // 2. Slow Rotation (Flow) - Randomized phase by X pos
        const rot = Math.sin(time * 0.5 + y * 0.1) * 0.1;

        ctx.rotate(rot);
        ctx.scale(pulse, pulse);

        ctx.globalAlpha = 0.9 * intensity;

        // Single draw call replaces the entire complex path/gradient/composite stack
        ctx.drawImage(texture, -half, -half, size, size);

        // Optional: Simple dynamic bubble (cheap)
        if (intensity > 0.8) {
            const bubbleX = Math.sin(time * 3 + x) * (HEX_SIZE * 0.4);
            const bubbleY = Math.cos(time * 2 + y) * (HEX_SIZE * 0.4);

            ctx.fillStyle = 'rgba(255,255,255,0.6)';
            ctx.beginPath(); 
            ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); 
            ctx.fill();
        }

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    // OPTIMIZED: Uses cached GLOW texture instead of real-time gradients
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;
        const halfSize = textureSize / 2;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        // Create cloud puffs
        const puffs = 4; // Reduced from 5
        for(let i=0; i<puffs; i++) {
            // Orbiting motion logic preserved
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5; // Scale relative to texture size
            const size = textureSize * scale;

            // Draw Cached Texture
            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        // Ground Haze (Base layer) using same texture stretched
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    // OPTIMIZED: Uses pre-baked CRACKS texture instead of procedural drawing
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        // Slight rotation for variety based on position (pseudo-random)
        // using x coordinate as seed to keep it static per tile
        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            // NOTE: Gradient here is still needed for depth, but it's only 3 per hex
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        // Optimized Seed: Use bitwise ops for speed
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                // Using the optimized drawGroundCracks which now uses cache
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            // VOID texture logic remains simple rects, but use context save/restore carefully
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LAVA' | 'FILL' | 'RING' | 'DASHED', color: string): HTMLCanvasElement {
        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'FILL') {
            // Pure fill, no stroke
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.95);
            ctx.fill();
        }
        else if (type === 'RING') {
            // Pure stroke, no glow
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'DASHED') {
            // Dashed stroke
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 8]);
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LAVA') {
            // High-Performance Baked Liquid
            // 1. Fluid Body
            ctx.fillStyle = color;
            // Use a slightly irregular shape for base
            ctx.beginPath();
            for(let i=0; i<=12; i++) {
                const a = (i/12) * Math.PI * 2;
                // Static noise for shape
                const noise = Math.sin(a * 3) * 5; 
                const rad = r * 0.9 + noise;
                const x = Math.cos(a) * rad;
                const y = Math.sin(a) * rad;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // 2. Inner Depth (Crust/Darker Pool)
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = color; 
            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.65, 0, Math.PI * 2); 
            ctx.fill();

            // 3. Specular Highlights (Gloss)
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            ctx.beginPath();
            ctx.ellipse(0, -r * 0.55, r * 0.4, 6, 0, 0, Math.PI*2);
            ctx.fill();

            // 4. Baked Bubbles (Static)
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(r*0.3, r*0.3, r*0.08, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-r*0.25, -r*0.15, r*0.05, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { Team } from "../../../types";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE } from "../../../constants";
import { VFXFactory } from "../../graphics/VFXFactory";

// Helper: Local Hexagon Trace (REMOVED in favor of Texture)
// Keeping simple draw for non-critical if needed, but we aim to replace all.

function drawHexTexture(
    ctx: CanvasRenderingContext2D, 
    texture: HTMLCanvasElement, 
    size: number, 
    alpha: number = 1.0
) {
    ctx.save();
    ctx.globalAlpha *= alpha;
    // Texture is 128px, center at 64. Scale to match 'size' radius.
    // texture 64 radius -> size radius. Scale = size / 64.
    const scale = size / 64; 
    ctx.scale(scale, scale);
    ctx.drawImage(texture, -64, -64);
    ctx.restore();
}

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    const feetX = Math.round(physX);
    const feetY = Math.round(physY - physZ); 

    ctx.save();
    ctx.translate(feetX, feetY); // Center at shadow point
    ctx.save();
    ctx.scale(1, 0.58); 

    // OPTIMIZED: Use DASHED Texture
    const texture = VFXFactory.getTexture('DASHED', color);

    // Animate rotation for "dash offset" effect or just rotate?
    // Native setLineDashOffset animates the dash along path. Rotation mimics movement.
    ctx.rotate(t * 0.5); 

    ctx.globalAlpha = 0.6;
    drawHexTexture(ctx, texture, 18);

    ctx.restore();

    if (physZ > 5) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(0, physZ); ctx.stroke(); // Vertical line from shadow to body
    }
    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 
    ctx.save();
    ctx.translate(0, 5); 
    ctx.scale(1, 0.5); 
    ctx.rotate(t * 8); 

    const alpha = 0.5 + Math.sin(t * 20) * 0.2; 

    // OPTIMIZED: Use OUTLINE Texture (already glowing)
    const texture = VFXFactory.getTexture('OUTLINE', color);
    drawHexTexture(ctx, texture, 15, alpha);

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // --- 1. HEXAGONAL ORBITAL BITS ---
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const orbitRadius = 25;

    // Pre-fetch texture
    const texture = VFXFactory.getTexture('SOLID', '#fff'); // White solid for bits

    for (let i = 0; i < 3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const ox = Math.round(Math.cos(t * 6 + offset) * orbitRadius);
        const oy = Math.round(Math.sin(t * 6 + offset) * orbitRadius * 0.5) - 35;

        ctx.save();
        ctx.translate(ox, oy);
        ctx.rotate(t * 10);

        // Shadow handles the color glow
        ctx.shadowColor = color; ctx.shadowBlur = 10;

        // OPTIMIZED: Draw Texture
        const bitSize = 4 * progress;
        drawHexTexture(ctx, texture, bitSize);

        ctx.restore();
    }
    ctx.restore();

    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    ctx.save();
    ctx.translate(0, -40); 
    const scale = 0.5 + progress * 0.5;
    ctx.scale(scale, scale * 0.5); 
    ctx.globalCompositeOperation = 'screen';
    ctx.rotate(t * 2);

    // OPTIMIZED: Use RING Texture
    const texture = VFXFactory.getTexture('RING', color);
    drawHexTexture(ctx, texture, 60);

    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -40); 
    const size = Math.round(50 * (0.2 + progress * 0.8));
    ctx.globalCompositeOperation = 'screen';

    // OPTIMIZED: Use FILL Textures
    const fillTex = VFXFactory.getTexture('FILL', color);
    const whiteTex = VFXFactory.getTexture('FILL', '#fff');

    drawHexTexture(ctx, fillTex, size, 0.3);
    drawHexTexture(ctx, whiteTex, size * 0.6, 0.5);

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    ctx.save();
    ctx.translate(Math.round(x), Math.round(y));

    // Calculate size
    const maxPx = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = maxPx * progress;

    ctx.scale(1, 0.58); // Isometric flatten

    // --- LAYER 1: BASE FIELD (Hex Fill) ---
    // OPTIMIZED: Use FILL Texture
    const fillTex = VFXFactory.getTexture('FILL', color);
    drawHexTexture(ctx, fillTex, currentRadius, 0.35);

    // --- LAYER 2: ENERGY RIM (Hex Glow) ---
    // OPTIMIZED: Use OUTLINE Texture (Glow built-in)
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const glowTex = VFXFactory.getTexture('OUTLINE', color);
    drawHexTexture(ctx, glowTex, currentRadius, 0.9);
    ctx.restore();

    // --- LAYER 3: RUNIC BORDER (Rotating Hex) ---
    // OPTIMIZED: Use DASHED Texture (White)
    ctx.save();
    ctx.rotate(t * 1.5); 
    const dashTex = VFXFactory.getTexture('DASHED', '#fff');
    drawHexTexture(ctx, dashTex, currentRadius + 2, 0.8);
    ctx.restore();

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, Math.round(-110));

            // OPTIMIZED: Hex Glow Background
            const alpha = 0.3 * (0.5 + Math.sin(t * 10) * 0.1);
            const tex = VFXFactory.getTexture('FILL', skill.color);
            drawHexTexture(ctx, tex, 40, alpha);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;
    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    if (agent.stunTimer > 0) {
        ctx.translate(0, Math.round(-65));
        const angle = t * 5;
        const x = Math.round(Math.cos(angle) * 20);
        const y = Math.round(Math.sin(angle) * 6); 

        // Spinning Star/Hex
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(t * 10);

        // OPTIMIZED: Use SOLID Texture (Gold)
        const tex = VFXFactory.getTexture('SOLID', '#facc15');
        drawHexTexture(ctx, tex, 4); // Small size

        ctx.restore();
    }
    ctx.restore();
}

import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { GroundHazard } from "../../../types";
import { VFXFactory } from "../../graphics/VFXFactory";

function drawHexTexture(
    ctx: CanvasRenderingContext2D, 
    texture: HTMLCanvasElement, 
    size: number, 
    alpha: number = 1.0
) {
    ctx.save();
    ctx.globalAlpha *= alpha;
    const scale = size / 64; 
    ctx.scale(scale, scale);
    ctx.drawImage(texture, -64, -64);
    ctx.restore();
}

// Procedural Helper REMOVED (traceHex)

export const ZoneRenderer = {

    drawActiveHazard(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        hazard: GroundHazard,
        globalTime: number
    ) {
        if (hazard.type === 'POISON' || hazard.type === 'GENERIC') {
            SurfaceAssets.drawVolumetricFog(ctx, x, y, hazard.color, globalTime);
        }
        else if (hazard.type === 'FIRE') {
            const intensity = 0.8 + Math.sin(globalTime * 3) * 0.2;
            SurfaceAssets.drawLiquidSurface(ctx, x, y, hazard.color, globalTime, intensity);
            SurfaceAssets.drawGroundCracks(ctx, x, y, '#fdba74', intensity);
        }
        else if (hazard.type === 'ICE') {
            SurfaceAssets.drawExtrudedHex(ctx, x, y, 5, hazard.color, 0.4, false);
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // OPTIMIZED: Use FILL Texture
            const tex = VFXFactory.getTexture('FILL', 'rgba(255, 255, 255, 0.2)');
            drawHexTexture(ctx, tex, size * 0.8);

            ctx.restore();
        }
        else if (hazard.type === 'GRAVITY') {
            // Hexagonal Black Hole
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // 1. Black Core
            const blackTex = VFXFactory.getTexture('FILL', '#000');
            drawHexTexture(ctx, blackTex, size * 0.9, 0.7);

            // 2. Spinning Ring
            ctx.rotate(globalTime * 2);
            const ringTex = VFXFactory.getTexture('RING', hazard.color);
            drawHexTexture(ctx, ringTex, size * 0.6);

            // 3. Offset Inner Ring
            ctx.rotate(1); 
            drawHexTexture(ctx, ringTex, size * 0.4);

            ctx.restore();
        }
    },

    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        type: 'CAST',
        visual: string,
        progress: number, 
        globalTime: number,
        dist: number, 
        maxRadius: number
    ) {
        const snapX = Math.floor(x);
        const snapY = Math.floor(y);

        ctx.save();
        ctx.translate(snapX, snapY);
        ctx.scale(1, ISO_SCALE_Y); 

        if (type === 'CAST') {
            const totalRadiusPx = Math.max(1, maxRadius) * HEX_SIZE * 1.5;
            const tileDistPx = dist * HEX_SIZE * 1.5;
            const normalizedDist = tileDistPx / totalRadiusPx;
            const wavePos = progress; 
            const bandWidth = 0.15;
            const distFromWave = Math.abs(normalizedDist - wavePos);

            // Draw Hex Ripple
            if (distFromWave < bandWidth) {
                const intensity = (1 - distFromWave / bandWidth);
                ctx.save();
                ctx.globalCompositeOperation = 'lighter';

                const alpha = intensity * (1.0 - progress * 0.5) * 0.8;

                // OPTIMIZED: Use FILL and RING Textures
                const fillTex = VFXFactory.getTexture('FILL', color);
                drawHexTexture(ctx, fillTex, size * 0.9, alpha);

                const ringTex = VFXFactory.getTexture('RING', '#fff');
                drawHexTexture(ctx, ringTex, size * 0.9, alpha);

                ctx.restore();
            } else if (normalizedDist < wavePos) {
                // Trailing fill
                const fillTex = VFXFactory.getTexture('FILL', color);
                drawHexTexture(ctx, fillTex, size * 0.8, 0.15 * (1.0 - progress * 0.5));
            }

            const isUlt = visual === 'ULT' || maxRadius >= 3; 
            if (isUlt && dist >= maxRadius - 0.5) {
                ctx.save();
                ctx.rotate(globalTime * 2);

                // OPTIMIZED: Use DASHED Texture
                const dashTex = VFXFactory.getTexture('DASHED', color);
                drawHexTexture(ctx, dashTex, size * 0.95);

                ctx.restore();
            }
        }

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        // Cache Key: Theme Type + Tier (Height)
        const key = `${type}_T${tier}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier);
        this.cache.set(key, canvas);
        return canvas;
    }

    private bakeBlock(theme: any, tier: number): HTMLCanvasElement {
        // Calculate Dimensions
        // Width: 2 * HEX_SIZE (plus padding)
        // Height: 2 * HEX_SIZE * ISO_SCALE + (tier * BLOCK_HEIGHT)
        const w = Math.ceil(HEX_SIZE * 2.2);
        const hOffset = Math.max(1, tier) * BLOCK_HEIGHT; 
        const h = Math.ceil((HEX_SIZE * 2 * ISO_SCALE_Y) + hOffset + 20); // +20 for stroke buffer

        const { canvas, ctx } = createCanvas(w, h);

        // Center Bottom anchor
        const cx = w / 2;
        const cy = h - 10; // Bottom margin

        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Only if height > 0)
        if (hOffset > 0) {
            const visibleIndices = [5, 0, 1];
            const BASE_THICKNESS = 12; // Visual "root" depth

            for (const i of visibleIndices) {
                const j = (i + 1) % 6;
                const c1 = HEX_CORNERS[i];
                const c2 = HEX_CORNERS[j];

                const x1 = cx + c1.x;
                const y1_top = cy + c1.y - hOffset;
                const x2 = cx + c2.x;
                const y2_top = cy + c2.y - hOffset;

                const y1_bottom = cy + c1.y + BASE_THICKNESS;
                const y2_bottom = cy + c2.y + BASE_THICKNESS;

                const grad = ctx.createLinearGradient(0, cy - hOffset, 0, cy + BASE_THICKNESS);
                const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

                grad.addColorStop(0, baseColor);
                grad.addColorStop(0.7, baseColor);
                grad.addColorStop(1, '#020617');

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(x1, y1_bottom);
                ctx.lineTo(x2, y2_bottom); 
                ctx.lineTo(x2, y2_top);    
                ctx.lineTo(x1, y1_top);    
                ctx.closePath();
                ctx.fill();

                // Horizontal Layer Lines (Stylistic)
                if (hOffset > BLOCK_HEIGHT) {
                    ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    for (let hStep = BLOCK_HEIGHT; hStep < hOffset; hStep += BLOCK_HEIGHT) {
                        ctx.moveTo(x1, cy + c1.y - hStep);
                        ctx.lineTo(x2, cy + c2.y - hStep);
                    }
                    ctx.stroke();
                }

                ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
                ctx.lineWidth = 1; 
                ctx.stroke();
            }
        }

        // 2. Draw Top Face
        this.pathTop(ctx, cx, faceY);
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];
        ctx.moveTo(cx + c4.x, faceY + c4.y);
        ctx.lineTo(cx + c3.x, faceY + c3.y);
        ctx.lineTo(cx + c2.x, faceY + c2.y); 
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        this.pathTop(ctx, cx, faceY);
        ctx.stroke();

        return canvas;
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
