import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { TerrainFactory } from "../../graphics/TerrainFactory";

// Geometry Helper (Kept for dynamic effects if needed, but mostly replaced by Factory)
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const TerrainRenderer = {

    // OPTIMIZED: Uses Baked Sprites
    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Calculate Tier (0-6)
        const tier = Math.round(height / BLOCK_HEIGHT);

        // 1. Fetch Baked Sprite
        const sprite = TerrainFactory.getBlock(theme, type, tier);

        // 2. Draw Sprite (Offset corrected for center-bottom anchor)
        // Factory makes canvas w=HEX*2.2, h=...
        // The anchor in factory is (cx, cy) where cy = h - 10
        // We draw at (x, y) which is the Ground Level point

        const w = sprite.width;
        const h = sprite.height;
        // Anchor offset matches Factory's cx, cy
        const drawX = x - w / 2;
        const drawY = y - (h - 10); 

        ctx.drawImage(sprite, drawX, drawY);

        // 3. Surface Assets (Dynamic overlays on top of the baked block)
        // These still need to be drawn manually as they animate
        const topY = y - height;

        if (type === 'MAGMA') {
            SurfaceAssets.drawLiquidSurface(ctx, x, topY, '#ef4444', globalTime, 1.0);
            const crackInt = 0.5 + Math.sin(globalTime) * 0.2;
            SurfaceAssets.drawGroundCracks(ctx, x, topY, '#fca5a5', crackInt);
        } else if (type === 'VOID') {
            SurfaceAssets.drawVolumetricFog(ctx, x, topY, theme.fogColor || '#6366f1', globalTime);
        } else if (type === 'ICE') {
            const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;
            ctx.save();
            this.traceTopFace(ctx, x, topY);
            ctx.clip(); 
            const specGrad = ctx.createLinearGradient(x - size, topY - size, x + size, topY + size);
            specGrad.addColorStop(0, 'transparent');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.3)'); 
            specGrad.addColorStop(1, 'transparent');
            ctx.translate(bandPos * 0.5, 0); 
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Detail texture layer (cracks, specks)
        SurfaceAssets.drawTexture(ctx, cx, cy, q, r, type, detailColor, performance.now() / 1000);
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { ZoneRenderer } from "./ZoneRenderer";
import { GroundHazard } from "../../../types";
import { VFXFactory } from "../../graphics/VFXFactory";
import { HEX_SIZE } from "../../../constants";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string;
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

// Helper for drawing cached hex textures
function drawHexTexture(ctx: CanvasRenderingContext2D, texture: HTMLCanvasElement, x: number, y: number, scale: number = 1.0) {
    ctx.save();
    ctx.translate(x, y);
    // Texture is 128x128, center at 64. 
    // Default size matches HEX_SIZE approx 36. 
    // We scale to fit.
    const texScale = (HEX_SIZE * 2.5 / 128) * scale;
    ctx.scale(texScale, texScale * 0.58); // flatten
    ctx.drawImage(texture, -64, -64);
    ctx.restore();
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual top Y
        size: number,
        specialStatus: string | undefined,
        zoneInfo: ZoneInfo | undefined,
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined // NEW
    ) {
        // 1. HAZARDS (Persistent Ground Effects)
        if (hazard) {
            ZoneRenderer.drawActiveHazard(ctx, x, y, size, hazard, globalTime);
        }

        // 2. SPECIAL STATUS FLOOR EFFECT (Unit State)
        if (specialStatus) {
            const color = (specialStatus === 'FROZEN') ? '#bae6fd' : 
                          (specialStatus === 'POLYMORPH') ? '#d8b4fe' : '#fde047';

            // OPTIMIZED: Use Cached Texture
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            ctx.globalAlpha = 0.6;
            drawHexTexture(ctx, VFXFactory.getTexture('FILL', color), x, y, 1.0);
            ctx.restore();
        }

        // 3. ZONE RENDERING (Cast Ripple)
        if (zoneInfo) {
            ZoneRenderer.draw(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.type,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // 4. Dynamic Lighting
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            // Use cached FILL for light
            drawHexTexture(ctx, VFXFactory.getTexture('FILL', lightColor), x, y, 1.1);
            ctx.restore();
        }

        // 5. Interactive Highlights (Optimization: Use Cached Textures)
        if (isRange || isHover || hasUnit) {

            if (isRange) { 
                // Range Fill + Outline
                ctx.save();
                ctx.globalAlpha = 0.05;
                drawHexTexture(ctx, VFXFactory.getTexture('FILL', rangeColor), x, y);
                ctx.globalAlpha = 0.6;
                // Use RING for outline
                drawHexTexture(ctx, VFXFactory.getTexture('RING', rangeColor), x, y);
                ctx.restore();
            }

            if (isHover) { 
                ctx.save();
                ctx.globalAlpha = 0.15;
                // White glow fill
                drawHexTexture(ctx, VFXFactory.getTexture('FILL', '#fff'), x, y);
                ctx.globalAlpha = 1.0;
                // Bright white outline
                drawHexTexture(ctx, VFXFactory.getTexture('OUTLINE', '#fff'), x, y);
                ctx.restore();
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.save();
                ctx.globalAlpha = 0.15;
                drawHexTexture(ctx, VFXFactory.getTexture('RING', '#fff'), x, y);
                ctx.restore();
            }
        }
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        // Cache Key: Theme Type + Tier (Height)
        const key = `${type}_T${tier}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier);
        this.cache.set(key, canvas);
        return canvas;
    }

    // New Helper to expose the visual center offset for the Renderer
    public getAnchorY(tier: number, canvasHeight: number): number {
        const hOffset = Math.max(1, tier) * BLOCK_HEIGHT;
        const bottomPadding = 20; 
        const cy = canvasHeight - bottomPadding;
        return cy - hOffset; // This is the Y coordinate of the Top Face Center in the sprite
    }

    private bakeBlock(theme: any, tier: number): HTMLCanvasElement {
        // Calculate Dimensions
        // Width: 2 * HEX_SIZE (plus padding)
        const w = Math.ceil(HEX_SIZE * 2.2);

        // Height Calculation Fix:
        // Top Face (ISO_SCALE) + Extrusion (hOffset) + Bottom Base Drop (12px) + Padding
        const hOffset = Math.max(1, tier) * BLOCK_HEIGHT; 
        const baseDrop = 15; 
        const bottomPadding = 20; // Increased to prevent clipping
        const topPadding = HEX_SIZE * ISO_SCALE_Y + 5;

        const h = Math.ceil(topPadding + hOffset + baseDrop + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Center Bottom anchor
        const cx = w / 2;
        // The "Ground Level" (Bottom of the hex column)
        const cy = h - bottomPadding;

        // The "Face Level" (Top of the hex column)
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Only if height > 0)
        if (hOffset > 0) {
            const visibleIndices = [5, 0, 1];
            // Visual "root" depth extending below ground level
            const BASE_THICKNESS = 12; 

            for (const i of visibleIndices) {
                const j = (i + 1) % 6;
                const c1 = HEX_CORNERS[i];
                const c2 = HEX_CORNERS[j];

                const x1 = cx + c1.x;
                const y1_top = faceY + c1.y; // Use faceY for top vertices
                const x2 = cx + c2.x;
                const y2_top = faceY + c2.y;

                const y1_bottom = cy + c1.y + BASE_THICKNESS;
                const y2_bottom = cy + c2.y + BASE_THICKNESS;

                const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
                const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

                grad.addColorStop(0, baseColor);
                grad.addColorStop(0.7, baseColor);
                grad.addColorStop(1, '#020617');

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(x1, y1_bottom);
                ctx.lineTo(x2, y2_bottom); 
                ctx.lineTo(x2, y2_top);    
                ctx.lineTo(x1, y1_top);    
                ctx.closePath();
                ctx.fill();

                // Horizontal Layer Lines (Stylistic)
                if (hOffset > BLOCK_HEIGHT) {
                    ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    for (let hStep = BLOCK_HEIGHT; hStep < hOffset; hStep += BLOCK_HEIGHT) {
                        ctx.moveTo(x1, faceY + c1.y + hStep);
                        ctx.lineTo(x2, faceY + c2.y + hStep);
                    }
                    ctx.stroke();
                }

                ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
                ctx.lineWidth = 1; 
                ctx.stroke();
            }
        }

        // 2. Draw Top Face
        this.pathTop(ctx, cx, faceY);
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // 3. Rim Light
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;
        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];
        ctx.moveTo(cx + c4.x, faceY + c4.y);
        ctx.lineTo(cx + c3.x, faceY + c3.y);
        ctx.lineTo(cx + c2.x, faceY + c2.y); 
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        this.pathTop(ctx, cx, faceY);
        ctx.stroke();

        return canvas;
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
}

