import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { TerrainFactory } from "../../graphics/TerrainFactory";

// Geometry Helper
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

export const TerrainRenderer = {

    // OPTIMIZED: Uses Baked Sprites
    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, // x, y is the Ground Level Center (z=0)
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Calculate Tier (0-6)
        const tier = Math.round(height / BLOCK_HEIGHT);

        // 1. Fetch Baked Sprite
        const sprite = TerrainFactory.getBlock(theme, type, tier);

        // 2. Alignment Logic
        const w = sprite.width;
        const h = sprite.height;

        // Retrieve the padding used during bake
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const baseThickness = 2;
        const bottomPadding = (sprite as any).bottomPadding || (hexVExtent + baseThickness + 4);

        // We want to align the sprite's Ground Pivot to (x, y)
        const groundAnchorY = TerrainFactory.getGroundAnchorY(h, bottomPadding);

        const drawX = x - w / 2;
        const drawY = y - groundAnchorY;

        ctx.drawImage(sprite, drawX, drawY);

        // 3. Surface Assets (Dynamic overlays)
        // These need to be drawn at the TOP FACE of the block
        const topY = y - height;

        if (type === 'MAGMA') {
            SurfaceAssets.drawLiquidSurface(ctx, x, topY, '#ef4444', globalTime, 1.0);
            const crackInt = 0.5 + Math.sin(globalTime) * 0.2;
            SurfaceAssets.drawGroundCracks(ctx, x, topY, '#fca5a5', crackInt);
        } else if (type === 'VOID') {
            SurfaceAssets.drawVolumetricFog(ctx, x, topY, theme.fogColor || '#6366f1', globalTime);
        } else if (type === 'ICE') {
            // FIX: Use topY for bandPos to ensure texture scrolls relative to surface, not ground
            const bandPos = (globalTime * 50 + x + topY) % (size * 4) - size * 2;
            ctx.save();
            this.traceTopFace(ctx, x, topY);
            ctx.clip(); 
            const specGrad = ctx.createLinearGradient(x - size, topY - size, x + size, topY + size);
            specGrad.addColorStop(0, 'transparent');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.3)'); 
            specGrad.addColorStop(1, 'transparent');
            ctx.translate(bandPos * 0.5, 0); 
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, // cy here is passed as Top Face Y from renderer.ts
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Detail texture layer (cracks, specks)
        SurfaceAssets.drawTexture(ctx, cx, cy, q, r, type, detailColor, performance.now() / 1000);
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier);
        this.cache.set(key, canvas);
        return canvas;
    }

    // Expose anchor point: The Visual Ground Level Center (Pivot)
    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        // The visual ground level (pivot) is at (Height - bottomPadding)
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number): HTMLCanvasElement {
        // FIX: Allow flat tiles (0 height) to ensure overlay alignment
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);

        // Base Thickness: Chunky slab base to prevent "paper floor" look
        const BASE_THICKNESS = 8; 

        // Padding calculation
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        // Ensure height is at least enough for one flat hex + base
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot (Ground Level Center)
        const cx = w / 2;
        const cy = h - bottomPadding; 

        // Visual Top Level Center
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Always draw sides (at least for the base thickness)
        const visibleIndices = [5, 0, 1]; // Left, Front-Left, Front-Right

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            // Top Vertices
            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            // Bottom Vertices (Extending slightly down for overlap)
            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Gradient for depth
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.6, baseColor);
            grad.addColorStop(1, theme.sideDark); // Solid darker bottom

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // Layer Lines (only if significant height)
            if (hOffset > BLOCK_HEIGHT * 1.5) {
                ctx.strokeStyle = 'rgba(0,0,0,0.1)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < hOffset; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, faceY + c1.y + hStep);
                    ctx.lineTo(x2, faceY + c2.y + hStep);
                }
                ctx.stroke();
            }

            // Edge Definition
            ctx.strokeStyle = 'rgba(0,0,0,0.2)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face
        this.pathTop(ctx, cx, faceY);

        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.2, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.fill();

        // 3. Rim Highlight
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.5;

        ctx.beginPath();
        const c4 = HEX_CORNERS[4];
        const c3 = HEX_CORNERS[3];
        const c2 = HEX_CORNERS[2];
        ctx.moveTo(cx + c4.x, faceY + c4.y);
        ctx.lineTo(cx + c3.x, faceY + c3.y);
        ctx.lineTo(cx + c2.x, faceY + c2.y); 
        ctx.stroke();

        // 4. Subtle Outline
        ctx.globalAlpha = 1.0;
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        this.pathTop(ctx, cx, faceY);
        ctx.stroke();

        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
}

export const TerrainFactory = new TerrainCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// Precomputed Hex for Geometry
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

const VISIBLE_FACES = [0, 1, 5]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LAVA', color);
        const size = HEX_SIZE * 2.5; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        // --- CLIP MASK START ---
        // Constrain to hex shape before transforming for liquid effect
        this.pathHex(ctx, 0, 0);
        ctx.clip();
        // --- CLIP MASK END ---

        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate fluid motion via transforms
        // 1. Breathing Scale (Pulsing heat)
        const pulse = 1.0 + Math.sin(time * 2 + x * 0.1) * 0.05;
        // 2. Slow Rotation (Flow) - Randomized phase by X pos
        const rot = Math.sin(time * 0.5 + y * 0.1) * 0.1;

        ctx.rotate(rot);
        ctx.scale(pulse, pulse);

        ctx.globalAlpha = 0.9 * intensity;

        ctx.drawImage(texture, -half, -half, size, size);

        // Optional: Simple dynamic bubble (cheap)
        if (intensity > 0.8) {
            const bubbleX = Math.sin(time * 3 + x) * (HEX_SIZE * 0.4);
            const bubbleY = Math.cos(time * 2 + y) * (HEX_SIZE * 0.4);

            ctx.fillStyle = 'rgba(255,255,255,0.6)';
            ctx.beginPath(); 
            ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); 
            ctx.fill();
        }

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;
        const halfSize = textureSize / 2;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        // Create cloud puffs
        const puffs = 4; // Reduced from 5
        for(let i=0; i<puffs; i++) {
            // Orbiting motion logic preserved
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5; // Scale relative to texture size
            const size = textureSize * scale;

            // Draw Cached Texture
            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        // Ground Haze (Base layer) using same texture stretched
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        // --- CLIP MASK START ---
        this.pathHex(ctx, 0, 0);
        ctx.clip();
        // --- CLIP MASK END ---

        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        // Slight rotation for variety based on position (pseudo-random)
        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            // NOTE: Gradient here is still needed for depth, but it's only 3 per hex
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        // Optimized Seed: Use bitwise ops for speed
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                // Using the optimized drawGroundCracks which now uses cache
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            // VOID texture logic remains simple rects, but use context save/restore carefully
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const BASE_THICKNESS = 8; 
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Improved: Richer gradients and texture lines
        const visibleIndices = [5, 0, 1]; // Left, Front-Left, Front-Right

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Side Gradient
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            // More dramatic lighting for sides
            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.4, baseColor);
            grad.addColorStop(1, 'rgba(0,0,0,0.8)'); // Deep shadow at bottom

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- DETAIL: Horizontal Strata Lines ---
            // Adds "texture" to the sides so they aren't flat plastic
            if (hOffset > 10) {
                ctx.save();
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                const step = 8; // Every 8 pixels
                for (let y = faceY + step; y < cy; y += step) {
                    // Calculate slope for isometric line
                    // Interpolate y based on x progress between x1 and x2? 
                    // Simpler: Just draw lines connecting the vertical edges at relative offsets
                    const ratio = (y - faceY) / hOffset;
                    // Actually, straight vertical offset works best for "layers"
                    ctx.moveTo(x1, y1_top + (y - faceY));
                    ctx.lineTo(x2, y2_top + (y - faceY));
                }
                ctx.stroke();
                ctx.restore();
            }

            // Side Edge Definition
            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Richer Top Gradient
        const topGrad = ctx.createRadialGradient(cx, faceY, 0, cx, faceY, HEX_SIZE);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.sideLight); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- DETAIL: Noise Texture on Top ---
        // Prevents the "flat" look by adding random speckles
        ctx.save();
        ctx.clip(); // Clip to hex
        const noiseCount = 40;
        for(let k=0; k<noiseCount; k++) {
            const nx = cx + (Math.random() - 0.5) * HEX_SIZE * 1.8;
            const ny = faceY + (Math.random() - 0.5) * HEX_SIZE * 1.0;
            const size = Math.random() * 2 + 1;
            ctx.fillStyle = Math.random() > 0.5 ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)';
            ctx.beginPath(); ctx.arc(nx, ny, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();

        // 3. Bevel / Highlight / Rim
        // Draw separate lines for lit edges (top/left) and shadowed edges (bottom/right)

        // Shadow Edges (Indices 0, 1, 2 - Front/Right/Bottom) roughly
        // Highlight Edges (Indices 3, 4, 5 - Back/Left/Top) roughly
        // Based on light source top-left

        // Inner Shadow (Soft ambient occlusion on the face itself)
        this.pathTop(ctx, cx, faceY);
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 3;
