import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const BASE_THICKNESS = 8; 
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Improved: Richer gradients and texture lines
        const visibleIndices = [5, 0, 1]; // Left, Front-Left, Front-Right

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Side Gradient
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight; 

            // More dramatic lighting for sides
            grad.addColorStop(0, baseColor);
            grad.addColorStop(0.4, baseColor);
            grad.addColorStop(1, 'rgba(0,0,0,0.8)'); // Deep shadow at bottom

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- DETAIL: Horizontal Strata Lines ---
            // Adds "texture" to the sides so they aren't flat plastic
            if (hOffset > 10) {
                ctx.save();
                ctx.strokeStyle = 'rgba(0,0,0,0.2)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                const step = 8; // Every 8 pixels
                for (let y = faceY + step; y < cy; y += step) {
                    // Calculate slope for isometric line
                    // Interpolate y based on x progress between x1 and x2? 
                    // Simpler: Just draw lines connecting the vertical edges at relative offsets
                    const ratio = (y - faceY) / hOffset;
                    // Actually, straight vertical offset works best for "layers"
                    ctx.moveTo(x1, y1_top + (y - faceY));
                    ctx.lineTo(x2, y2_top + (y - faceY));
                }
                ctx.stroke();
                ctx.restore();
            }

            // Side Edge Definition
            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Richer Top Gradient
        const topGrad = ctx.createRadialGradient(cx, faceY, 0, cx, faceY, HEX_SIZE);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.sideLight); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- DETAIL: Noise Texture on Top ---
        // Prevents the "flat" look by adding random speckles
        ctx.save();
        ctx.clip(); // Clip to hex
        const noiseCount = 40;
        for(let k=0; k<noiseCount; k++) {
            const nx = cx + (Math.random() - 0.5) * HEX_SIZE * 1.8;
            const ny = faceY + (Math.random() - 0.5) * HEX_SIZE * 1.0;
            const size = Math.random() * 2 + 1;
            ctx.fillStyle = Math.random() > 0.5 ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)';
            ctx.beginPath(); ctx.arc(nx, ny, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();

        // 3. Bevel / Highlight / Rim
        // Draw separate lines for lit edges (top/left) and shadowed edges (bottom/right)

        // Shadow Edges (Indices 0, 1, 2 - Front/Right/Bottom) roughly
        // Highlight Edges (Indices 3, 4, 5 - Back/Left/Top) roughly
        // Based on light source top-left

        // Inner Shadow (Soft ambient occlusion on the face itself)
        this.pathTop(ctx, cx, faceY);
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // Sharp Highlight (Rim) - Top/Back edges
        ctx.beginPath();
        const c3 = HEX_CORNERS[3];
        const c4 = HEX_CORNERS[4];
        const c5 = HEX_CORNERS[5];
        const c0 = HEX_CORNERS[0]; // Connector

        ctx.moveTo(cx + c3.x, faceY + c3.y);
        ctx.lineTo(cx + c4.x, faceY + c4.y);
        ctx.lineTo(cx + c5.x, faceY + c5.y);
        ctx.lineTo(cx + c0.x, faceY + c0.y);

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.4)';
        ctx.stroke();

        // Sharp Shadow - Bottom/Front edges
        ctx.beginPath();
        const c1 = HEX_CORNERS[1];
        const c2 = HEX_CORNERS[2];

        ctx.moveTo(cx + c0.x, faceY + c0.y);
        ctx.lineTo(cx + c1.x, faceY + c1.y);
        ctx.lineTo(cx + c2.x, faceY + c2.y);
        ctx.lineTo(cx + c3.x, faceY + c3.y);

        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 1.0;
        ctx.stroke();

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
}

export const TerrainFactory = new TerrainCache();

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}_V2`; // V2 for new visuals
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const BASE_THICKNESS = 12; // Thicker base for more weight
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // LIGHTING MODEL: Top-Left Light Source
        // Face 5 (Left-Back in array logic, visually Left): Brightest
        // Face 0 (Front): Medium
        // Face 1 (Right): Darkest
        const faces = [
            { idx: 5, light: 1.2, label: 'LEFT' },
            { idx: 0, light: 0.9, label: 'FRONT' },
            { idx: 1, light: 0.6, label: 'RIGHT' }
        ];

        for (const face of faces) {
            const i = face.idx;
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Base Color with Directional Lighting
            const baseColor = (i === 5) ? theme.sideLight : theme.sideDark; 

            // Vertical Gradient for Ambient Occlusion (Darker at bottom)
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(baseColor, face.light));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.5)); // Deep shadow at foot

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- SIDE TEXTURE DETAILS ---
            ctx.save();
            ctx.clip(); // Clip drawing to this face

            ctx.globalCompositeOperation = 'overlay';
            ctx.globalAlpha = 0.3;

            if (type === 'VOID' || type === 'MAGMA') {
                // Horizontal Tech Lines / Strata
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let ly = faceY; ly < cy + BASE_THICKNESS; ly += 6) {
                    ctx.moveTo(x1, ly + c1.y); // Rough approximation of perspective
                    ctx.lineTo(x2, ly + c2.y);
                }
                ctx.stroke();
            } else if (type === 'ICE' || type === 'FOREST') {
                // Vertical Streaks (Ice pillars / Tree bark)
                ctx.strokeStyle = (type === 'ICE') ? '#fff' : '#000';
                ctx.globalAlpha = 0.15;
                ctx.lineWidth = 2;
                ctx.beginPath();
                const step = (x2 - x1) / 5;
                for (let k = 1; k < 5; k++) {
                    const lx = x1 + k * step;
                    ctx.moveTo(lx, faceY - 20);
                    ctx.lineTo(lx, cy + 20);
                }
                ctx.stroke();
            }

            ctx.restore();

            // Edge Definition
            ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Richer Top Gradient (Simulate sun spot)
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.3)); // Highlight top-left
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- TOP TEXTURE GENERATION ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. Bevel / Highlight / Rim
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        this.pathTop(ctx, cx, cy);
        ctx.clip();

        if (type === 'FOREST') {
            // Grass Tufts
            ctx.strokeStyle = theme.detail; // Light green
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.6;
            for(let k=0; k<25; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.6;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.2;
                // Draw small 'v' shapes
                ctx.beginPath();
                ctx.moveTo(tx - 2, ty - 3);
                ctx.lineTo(tx, ty);
                ctx.lineTo(tx + 2, ty - 3);
                ctx.stroke();
            }
            // Dirt patches
            ctx.fillStyle = '#3f2e05';
            ctx.globalAlpha = 0.1;
            for(let k=0; k<5; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                const r = Math.random() * 8 + 4;
                ctx.beginPath(); ctx.arc(tx, ty, r, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'ICE') {
            // Sharp white scratches
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            for(let k=0; k<10; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.5;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.0;
                const len = Math.random() * 15;
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + len, ty + len * 0.5);
            }
            ctx.stroke();

            // Reflective facets
            ctx.fillStyle = '#fff';
            ctx.globalCompositeOperation = 'overlay';
            ctx.globalAlpha = 0.2;
            for(let k=0; k<4; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx+10, ty-5);
                ctx.lineTo(tx+5, ty+10);
                ctx.fill();
            }

        } else if (type === 'MAGMA') {
            // Glowing cracks
            ctx.strokeStyle = theme.detail; // Bright Red/Orange
            ctx.lineWidth = 2;
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.6;
            ctx.lineCap = 'round';
            for(let k=0; k<5; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + (Math.random()-0.5)*20, ty + (Math.random()-0.5)*15);
                ctx.lineTo(tx + (Math.random()-0.5)*20, ty + (Math.random()-0.5)*15);
                ctx.stroke();
            }
            // Dark obsidian spots
            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = '#1a0505';
            ctx.globalAlpha = 0.3;
            for(let k=0; k<8; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.5;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                const r = Math.random() * 6 + 2;
                ctx.beginPath(); ctx.arc(tx, ty, r, 0, Math.PI*2); ctx.fill();
            }

        } else if (type === 'DESERT') {
            // Sand ripples (Sine waves)
            ctx.strokeStyle = theme.rim;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.3;
            ctx.beginPath();
            for(let yOffset = -HEX_SIZE/2; yOffset < HEX_SIZE/2; yOffset += 8) {
                for(let x = -HEX_SIZE; x < HEX_SIZE; x+=5) {
                    const y = cy + yOffset + Math.sin(x * 0.1) * 3;
                    const px = cx + x;
                    if(x===-HEX_SIZE) ctx.moveTo(px, y);
                    else ctx.lineTo(px, y);
                }
            }
            ctx.stroke();

        } else if (type === 'VOID') {
            // Tech Grid
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            const step = 8;
            ctx.beginPath();
            // Isometric grid lines approximation
            for(let i = -HEX_SIZE; i < HEX_SIZE; i+=step) {
                ctx.moveTo(cx + i, cy - HEX_SIZE/2);
                ctx.lineTo(cx + i, cy + HEX_SIZE/2);
            }
            for(let i = -HEX_SIZE/2; i < HEX_SIZE/2; i+=step) {
                ctx.moveTo(cx - HEX_SIZE, cy + i);
                ctx.lineTo(cx + HEX_SIZE, cy + i);
            }
            ctx.stroke();

            // Glowing nodes
            ctx.fillStyle = theme.rim;
            ctx.globalCompositeOperation = 'lighter';
            for(let k=0; k<6; k++) {
                if(Math.random()>0.5) {
                    const tx = cx + (Math.random()-0.5)*HEX_SIZE;
                    const ty = cy + (Math.random()-0.5)*HEX_SIZE*0.8;
                    ctx.fillRect(tx, ty, 2, 2);
                }
            }
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // Inner Shadow (Soft ambient occlusion on the face itself)
        this.pathTop(ctx, cx, cy);
        ctx.strokeStyle = 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 4;
        ctx.stroke();

        // Sharp Highlight (Rim) - Top/Back/Left edges (Sun direction)
        ctx.beginPath();
        const c3 = HEX_CORNERS[3]; // Top Left
        const c4 = HEX_CORNERS[4]; // Top
        const c5 = HEX_CORNERS[5]; // Top Right (Visual Left)
        const c0 = HEX_CORNERS[0]; // Right

        // Highlight logic: 3->4->5 is the top-back edge catching light
        ctx.moveTo(cx + c0.x, cy + c0.y); // Start right
        ctx.lineTo(cx + c5.x, cy + c5.y); // To Top Right
        ctx.lineTo(cx + c4.x, cy + c4.y); // To Top
        ctx.lineTo(cx + c3.x, cy + c3.y); // To Top Left

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.5)';
        ctx.stroke();

        // Sharp Shadow - Bottom/Front edges
        ctx.beginPath();
        const c1 = HEX_CORNERS[1]; // Bottom Right
        const c2 = HEX_CORNERS[2]; // Bottom Left

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c1.x, cy + c1.y);
        ctx.lineTo(cx + c2.x, cy + c2.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.strokeStyle = 'rgba(0,0,0,0.25)'; // Stronger shadow
        ctx.lineWidth = 1.5;
        ctx.stroke();
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }

    private adjustBrightness(hex: string, factor: number): string {
        // Simple hex brightness adjuster
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

