        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Improved: distinct light levels for true 3D feel
        const faces = [
            { idx: 5, light: 1.15, label: 'LEFT' },  // Key Light
            { idx: 0, light: 0.85, label: 'FRONT' }, // Fill Light
            { idx: 1, light: 0.55, label: 'RIGHT' }  // Shadow Side
        ];

        for (const face of faces) {
            const i = face.idx;
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Side Base Color
            const rawColor = (i === 5) ? theme.sideLight : theme.sideDark; 

            // Advanced Gradient: Top is lit, bottom creates ambient occlusion
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(rawColor, face.light));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.4)); // Ground occlusion

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- PROCEDURAL SIDE TEXTURE ---
            ctx.save();
            ctx.clip(); 

            // Strata / Layers
            if (type === 'MAGMA' || type === 'DESERT' || type === 'VOID') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 0.2;
                const layerHeight = type === 'VOID' ? 4 : 8;
                for(let ly = faceY; ly < cy + BASE_THICKNESS; ly += layerHeight * 2) {
                    // Draw horizontal strips
                    ctx.beginPath();
                    // Isometric slope approximation
                    const slope = (y2_top - y1_top) / (x2 - x1);
                    const yStart = ly;
                    const yEnd = ly + (x2 - x1) * slope;

                    ctx.moveTo(x1, yStart);
                    ctx.lineTo(x2, yEnd);
                    ctx.lineTo(x2, yEnd + layerHeight);
                    ctx.lineTo(x1, yStart + layerHeight);
                    ctx.fill();
                }
            } 
            // Vertical Striations (Ice/Forest)
            else if (type === 'ICE' || type === 'FOREST') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.strokeStyle = (type === 'ICE') ? '#fff' : '#000';
                ctx.globalAlpha = (type === 'ICE') ? 0.3 : 0.15;
                ctx.lineWidth = 2;

                const steps = 6;
                const dx = (x2 - x1) / steps;
                const dy = (y2_top - y1_top) / steps;

                for(let k=1; k<steps; k++) {
                    const sx = x1 + k * dx;
                    const sy = y1_top + k * dy;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    ctx.lineTo(sx, sy + 300); // Straight down
                    ctx.stroke();
                }
            }
            ctx.restore();

            // Edge Definition (Anti-aliasing help)
            ctx.strokeStyle = 'rgba(0,0,0,0.2)'; 
            ctx.lineWidth = 0.5; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Spotlight Gradient (Top-Left to Bottom-Right)
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.25)); 
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- PROCEDURAL TOP TEXTURE (The Juice) ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. High-Definition Bevels
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        this.pathTop(ctx, cx, cy);
        ctx.clip();

        if (type === 'FOREST') {
            // Stippling / Grass Tufts
            // Darker patches
            ctx.fillStyle = this.adjustBrightness(theme.top, 0.8);
            for(let i=0; i<15; i++) {
                const r = 4 + Math.random() * 6;
                const x = cx + (Math.random()-0.5) * HEX_SIZE * 1.5;
                const y = cy + (Math.random()-0.5) * HEX_SIZE * 1.0;
                ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
            }
            // Grass blades
            ctx.strokeStyle = theme.detail; 
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.5;
            for(let k=0; k<40; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.7;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.2;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 2, ty - 3);
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            // Crystalline Facets
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.2;

            for(let k=0; k<6; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.2;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*0.8;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 15, ty + 5);
                ctx.lineTo(tx + 5, ty + 10);
                ctx.fill();
            }
            // Sharp scratches
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            for(let k=0; k<8; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.5;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                const len = 10 + Math.random() * 10;
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + len, ty + len * 0.5);
            }
            ctx.stroke();

        } else if (type === 'MAGMA') {
            // Cooling Crust
            ctx.fillStyle = '#2a0a0a'; // Obsidian
            ctx.globalAlpha = 0.4;
            for(let k=0; k<12; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.6;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.0;
                const r = 5 + Math.random() * 8;
                ctx.beginPath(); 
                // Irregular polygon
                ctx.moveTo(tx+r, ty);
                ctx.lineTo(tx, ty+r);
                ctx.lineTo(tx-r, ty);
                ctx.lineTo(tx, ty-r);
                ctx.fill();
            }
            // Glowing Veins
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = '#f87171';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.moveTo(cx-15, cy); ctx.lineTo(cx+15, cy+5);
            ctx.moveTo(cx, cy-10); ctx.lineTo(cx+5, cy+15);
            ctx.stroke();

        } else if (type === 'DESERT') {
            // Dunes / Ripples
            ctx.strokeStyle = this.adjustBrightness(theme.top, 0.85); // Darker sand
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4;

            for(let i=0; i<5; i++) {
                const offset = (i - 2) * 10;
                ctx.beginPath();
                // Sine wave curve
                for(let x = -20; x <= 20; x+=5) {
                    const y = Math.sin(x * 0.2) * 4;
                    if(x===-20) ctx.moveTo(cx + x + offset, cy + y + offset*0.5);
                    else ctx.lineTo(cx + x + offset, cy + y + offset*0.5);
                }
                ctx.stroke();
            }

        } else if (type === 'VOID') {
            // Hex Grid Overlay
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;

            const gridSize = 10;
            ctx.beginPath();
            // Isogrid
            for (let x = -HEX_SIZE; x < HEX_SIZE; x += gridSize) {
                ctx.moveTo(cx + x, cy - HEX_SIZE);
                ctx.lineTo(cx + x, cy + HEX_SIZE);
            }
            ctx.stroke();

            // Circuit Nodes
            ctx.fillStyle = theme.rim;
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.8;
            for(let k=0; k<4; k++) {
                const tx = cx + (Math.floor(Math.random()*4)-2) * gridSize;
                const ty = cy + (Math.floor(Math.random()*4)-2) * gridSize * 0.6;
                ctx.fillRect(tx-1, ty-1, 3, 3);
            }
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // 1. Inner Ambient Occlusion (Soft Shadow inside the hex)
        this.pathTop(ctx, cx, cy);
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // 2. High-Contrast Rim Light (Top/Left edges)
        // This gives the "sharpness"
        ctx.beginPath();
        const c3 = HEX_CORNERS[3]; // Top Left
        const c4 = HEX_CORNERS[4]; // Top
        const c5 = HEX_CORNERS[5]; // Top Right
        const c0 = HEX_CORNERS[0]; // Right Connector

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c5.x, cy + c5.y);
        ctx.lineTo(cx + c4.x, cy + c4.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5; // Thinner but brighter
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.6)';
        ctx.stroke();

        // 3. Drop Shadow Rim (Bottom/Right edges)
        ctx.beginPath();
        const c1 = HEX_CORNERS[1]; // Bottom Right
        const c2 = HEX_CORNERS[2]; // Bottom Left

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c1.x, cy + c1.y);
        ctx.lineTo(cx + c2.x, cy + c2.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.strokeStyle = 'rgba(0,0,0,0.3)'; // Stronger dark line
        ctx.lineWidth = 1.0;
        ctx.stroke();
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }

    private adjustBrightness(hex: string, factor: number): string {
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

export const TerrainFactory = new TerrainCache();

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Standardized Dimensions for alignment
        // Renderer draws at (x - width/2), so cx must be exactly width/2.
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);

        const cx = 40; // Exact Center
        const cy = 95; // Ground Anchor Y (Matches GridSystem's OBSTACLE_ANCHOR_Y)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion)
        // Must be centered at cx, cy
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 24, 12, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#291815'; // Darker Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy + 2); // Base slightly below pivot for grounding
            ctx.lineTo(cx + 6, cy + 2);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); // Bright Tip
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); // Dark Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                // Edge Highlight (Rim)
                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1.5;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1.5;
                ctx.stroke();

                ctx.restore();
            };

            // Centered cluster
            drawCrystal(cx - 12, cy - 2, 8, 35, -0.25);
            drawCrystal(cx + 10, cy, 10, 30, 0.3);
            drawCrystal(cx, cy + 5, 14, 60, 0); // Main center shard

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 70;
            const w = 22;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, style.light);
            rockGrad.addColorStop(0.4, style.main);
            rockGrad.addColorStop(1, style.dark);
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 8, cy + 2); // Base Right (Grounded)
            ctx.lineTo(cx - 8, cy + 2); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 8;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 4, cy - 10); ctx.lineTo(cx + 4, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 30;
            let currentW = w;
            let currentY = cy; // Start from ground

            for(let i=0; i<layers; i++) {
                const h = 12 + Math.random() * 4;
                const nextY = currentY - h;
                const nextW = currentW * (0.65 + Math.random() * 0.2); // Taper up

                // Gradient for rounded volume
                const grad = ctx.createLinearGradient(cx - currentW, 0, cx + currentW, 0);
                const color = i % 2 === 0 ? style.main : style.light;
                grad.addColorStop(0, style.dark);
                grad.addColorStop(0.2, color);
                grad.addColorStop(0.8, color);
                grad.addColorStop(1, style.dark);
                ctx.fillStyle = grad;

                // Base Oval
                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 8, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Top Highlight Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.ellipse(cx, nextY, nextW, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.globalAlpha = 1.0;

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- WALL / STONE PILLAR ---
            const w = 28; // Half width
            const h = 55; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8); // Isometric top-right
            ctx.lineTo(cx + w, cy - 8);   // Bottom-right
            ctx.lineTo(cx, cy + 2);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 8);
            ctx.lineTo(cx - w, cy - 8);
            ctx.lineTo(cx, cy + 2);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8);
            ctx.lineTo(cx, topY + 16); // Center-down
            ctx.lineTo(cx - w, topY + 8);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 8); ctx.lineTo(cx, topY + 16); ctx.lineTo(cx - w, topY + 8); ctx.lineTo(cx, topY);
            ctx.stroke();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = 48;
        const cy = 108; // Ground anchor

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        // Cluster of ice shards
        drawShard(cx - 15, cy, 12, 50, -0.3);
        drawShard(cx + 15, cy - 5, 14, 45, 0.3);
        drawShard(cx, cy + 5, 20, 80, 0); // Main center shard

        return canvas;
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}_V3`; // V3: High Fidelity
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const BASE_THICKNESS = 14; // Thicker base for better occlusion
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Improved: distinct light levels for true 3D feel
        const faces = [
            { idx: 5, light: 1.15, label: 'LEFT' },  // Key Light
            { idx: 0, light: 0.85, label: 'FRONT' }, // Fill Light
            { idx: 1, light: 0.55, label: 'RIGHT' }  // Shadow Side
        ];

        for (const face of faces) {
            const i = face.idx;
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Side Base Color
            const rawColor = (i === 5) ? theme.sideLight : theme.sideDark; 

            // Advanced Gradient: Top is lit, bottom creates ambient occlusion
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(rawColor, face.light));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.4)); // Ground occlusion

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- PROCEDURAL SIDE TEXTURE ---
            ctx.save();
            ctx.clip(); 

            // Strata / Layers
            if (type === 'MAGMA' || type === 'DESERT' || type === 'VOID') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 0.2;
                const layerHeight = type === 'VOID' ? 4 : 8;
                for(let ly = faceY; ly < cy + BASE_THICKNESS; ly += layerHeight * 2) {
                    // Draw horizontal strips
                    ctx.beginPath();
                    // Isometric slope approximation
                    const slope = (y2_top - y1_top) / (x2 - x1);
                    const yStart = ly;
                    const yEnd = ly + (x2 - x1) * slope;

                    ctx.moveTo(x1, yStart);
                    ctx.lineTo(x2, yEnd);
                    ctx.lineTo(x2, yEnd + layerHeight);
                    ctx.lineTo(x1, yStart + layerHeight);
                    ctx.fill();
                }
            } 
            // Vertical Striations (Ice/Forest)
            else if (type === 'ICE' || type === 'FOREST') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.strokeStyle = (type === 'ICE') ? '#fff' : '#000';
                ctx.globalAlpha = (type === 'ICE') ? 0.3 : 0.15;
                ctx.lineWidth = 2;

                const steps = 6;
                const dx = (x2 - x1) / steps;
                const dy = (y2_top - y1_top) / steps;

                for(let k=1; k<steps; k++) {
                    const sx = x1 + k * dx;
                    const sy = y1_top + k * dy;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    ctx.lineTo(sx, sy + 300); // Straight down
                    ctx.stroke();
                }
            }
            ctx.restore();

            // Edge Definition (Anti-aliasing help)
            ctx.strokeStyle = 'rgba(0,0,0,0.2)'; 
            ctx.lineWidth = 0.5; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Spotlight Gradient (Top-Left to Bottom-Right)
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.25)); 
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- PROCEDURAL TOP TEXTURE (The Juice) ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. High-Definition Bevels
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        this.pathTop(ctx, cx, cy);
        ctx.clip();

        if (type === 'FOREST') {
            // Stippling / Grass Tufts
            // Darker patches
            ctx.fillStyle = this.adjustBrightness(theme.top, 0.8);
            for(let i=0; i<15; i++) {
                const r = 4 + Math.random() * 6;
                const x = cx + (Math.random()-0.5) * HEX_SIZE * 1.5;
                const y = cy + (Math.random()-0.5) * HEX_SIZE * 1.0;
                ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
            }
            // Grass blades
            ctx.strokeStyle = theme.detail; 
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.5;
            for(let k=0; k<40; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.7;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.2;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 2, ty - 3);
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            // Crystalline Facets
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.2;

            for(let k=0; k<6; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.2;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*0.8;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 15, ty + 5);
                ctx.lineTo(tx + 5, ty + 10);
                ctx.fill();
            }
            // Sharp scratches
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            for(let k=0; k<8; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.5;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                const len = 10 + Math.random() * 10;
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + len, ty + len * 0.5);
            }
            ctx.stroke();

        } else if (type === 'MAGMA') {
            // Cooling Crust
            ctx.fillStyle = '#2a0a0a'; // Obsidian
            ctx.globalAlpha = 0.4;
            for(let k=0; k<12; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.6;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.0;
                const r = 5 + Math.random() * 8;
                ctx.beginPath(); 
                // Irregular polygon
                ctx.moveTo(tx+r, ty);
                ctx.lineTo(tx, ty+r);
                ctx.lineTo(tx-r, ty);
                ctx.lineTo(tx, ty-r);
                ctx.fill();
            }
            // Glowing Veins
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = '#f87171';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.moveTo(cx-15, cy); ctx.lineTo(cx+15, cy+5);
            ctx.moveTo(cx, cy-10); ctx.lineTo(cx+5, cy+15);
            ctx.stroke();

        } else if (type === 'DESERT') {
            // Dunes / Ripples
            ctx.strokeStyle = this.adjustBrightness(theme.top, 0.85); // Darker sand
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4;

            for(let i=0; i<5; i++) {
                const offset = (i - 2) * 10;
                ctx.beginPath();
                // Sine wave curve
                for(let x = -20; x <= 20; x+=5) {
                    const y = Math.sin(x * 0.2) * 4;
                    if(x===-20) ctx.moveTo(cx + x + offset, cy + y + offset*0.5);
                    else ctx.lineTo(cx + x + offset, cy + y + offset*0.5);
                }
                ctx.stroke();
            }

        } else if (type === 'VOID') {
            // Hex Grid Overlay
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;

            const gridSize = 10;
            ctx.beginPath();
            // Isogrid
            for (let x = -HEX_SIZE; x < HEX_SIZE; x += gridSize) {
                ctx.moveTo(cx + x, cy - HEX_SIZE);
                ctx.lineTo(cx + x, cy + HEX_SIZE);
            }
            ctx.stroke();

            // Circuit Nodes
            ctx.fillStyle = theme.rim;
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.8;
            for(let k=0; k<4; k++) {
                const tx = cx + (Math.floor(Math.random()*4)-2) * gridSize;
                const ty = cy + (Math.floor(Math.random()*4)-2) * gridSize * 0.6;
                ctx.fillRect(tx-1, ty-1, 3, 3);
            }
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // 1. Inner Ambient Occlusion (Soft Shadow inside the hex)
        this.pathTop(ctx, cx, cy);
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // 2. High-Contrast Rim Light (Top/Left edges)
        // This gives the "sharpness"
        ctx.beginPath();
        const c3 = HEX_CORNERS[3]; // Top Left
        const c4 = HEX_CORNERS[4]; // Top
        const c5 = HEX_CORNERS[5]; // Top Right
        const c0 = HEX_CORNERS[0]; // Right Connector

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c5.x, cy + c5.y);
        ctx.lineTo(cx + c4.x, cy + c4.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5; // Thinner but brighter
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.6)';
        ctx.stroke();

        // 3. Drop Shadow Rim (Bottom/Right edges)
        ctx.beginPath();
        const c1 = HEX_CORNERS[1]; // Bottom Right
        const c2 = HEX_CORNERS[2]; // Bottom Left

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c1.x, cy + c1.y);
        ctx.lineTo(cx + c2.x, cy + c2.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.strokeStyle = 'rgba(0,0,0,0.3)'; // Stronger dark line
        ctx.lineWidth = 1.0;
        ctx.stroke();
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }

    private adjustBrightness(hex: string, factor: number): string {
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

export const TerrainFactory = new TerrainCache();

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Standardized Dimensions for alignment
        // Renderer draws at (x - width/2), so cx must be exactly width/2.
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);

        const cx = 40; // Exact Center
        const cy = 95; // Ground Anchor Y (Matches GridSystem's OBSTACLE_ANCHOR_Y)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion)
        // Must be centered at cx, cy
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 24, 12, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#291815'; // Darker Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy + 2); // Base slightly below pivot for grounding
            ctx.lineTo(cx + 6, cy + 2);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); // Bright Tip
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); // Dark Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                // Edge Highlight (Rim)
                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1.5;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1.5;
                ctx.stroke();

                ctx.restore();
            };

            // Centered cluster
            drawCrystal(cx - 12, cy - 2, 8, 35, -0.25);
            drawCrystal(cx + 10, cy, 10, 30, 0.3);
            drawCrystal(cx, cy + 5, 14, 60, 0); // Main center shard

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 70;
            const w = 22;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, style.light);
            rockGrad.addColorStop(0.4, style.main);
            rockGrad.addColorStop(1, style.dark);
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 8, cy + 2); // Base Right (Grounded)
            ctx.lineTo(cx - 8, cy + 2); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 8;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 4, cy - 10); ctx.lineTo(cx + 4, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 30;
            let currentW = w;
            let currentY = cy; // Start from ground

            for(let i=0; i<layers; i++) {
                const h = 12 + Math.random() * 4;
                const nextY = currentY - h;
                const nextW = currentW * (0.65 + Math.random() * 0.2); // Taper up

                // Gradient for rounded volume
                const grad = ctx.createLinearGradient(cx - currentW, 0, cx + currentW, 0);
                const color = i % 2 === 0 ? style.main : style.light;
                grad.addColorStop(0, style.dark);
                grad.addColorStop(0.2, color);
                grad.addColorStop(0.8, color);
                grad.addColorStop(1, style.dark);
                ctx.fillStyle = grad;

                // Base Oval
                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 8, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Top Highlight Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.ellipse(cx, nextY, nextW, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.globalAlpha = 1.0;

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- WALL / STONE PILLAR ---
            const w = 28; // Half width
            const h = 55; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8); // Isometric top-right
            ctx.lineTo(cx + w, cy - 8);   // Bottom-right
            ctx.lineTo(cx, cy + 2);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 8);
            ctx.lineTo(cx - w, cy - 8);
            ctx.lineTo(cx, cy + 2);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8);
            ctx.lineTo(cx, topY + 16); // Center-down
            ctx.lineTo(cx - w, topY + 8);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 8); ctx.lineTo(cx, topY + 16); ctx.lineTo(cx - w, topY + 8); ctx.lineTo(cx, topY);
            ctx.stroke();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = 48;
        const cy = 108; // Ground anchor

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        // Cluster of ice shards
        drawShard(cx - 15, cy, 12, 50, -0.3);
        drawShard(cx + 15, cy - 5, 14, 45, 0.3);
        drawShard(cx, cy + 5, 20, 80, 0); // Main center shard

        return canvas;
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Precomputed Geometry
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}_V4`; // V4: High Fidelity & Textures
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- GEOMETRY METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        const BASE_THICKNESS = 14; // Thicker base for better occlusion
        const bottomPadding = hexVExtent + BASE_THICKNESS + 4; 
        const topPadding = hexVExtent + 4;

        const w = Math.ceil(HEX_SIZE * 2.2);
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot
        const cx = w / 2;
        const cy = h - bottomPadding; 
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Improved: distinct light levels for true 3D feel
        const faces = [
            { idx: 5, light: 1.15, label: 'LEFT' },  // Key Light
            { idx: 0, light: 0.85, label: 'FRONT' }, // Fill Light
            { idx: 1, light: 0.55, label: 'RIGHT' }  // Shadow Side
        ];

        for (const face of faces) {
            const i = face.idx;
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Side Base Color
            const rawColor = (i === 5) ? theme.sideLight : theme.sideDark; 

            // Advanced Gradient: Top is lit, bottom creates ambient occlusion
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(rawColor, face.light));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.4)); // Ground occlusion

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // --- PROCEDURAL SIDE TEXTURE ---
            ctx.save();
            ctx.clip(); 

            // Strata / Layers
            if (type === 'MAGMA' || type === 'DESERT' || type === 'VOID') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 0.2;
                const layerHeight = type === 'VOID' ? 4 : 8;
                for(let ly = faceY; ly < cy + BASE_THICKNESS; ly += layerHeight * 2) {
                    // Draw horizontal strips
                    ctx.beginPath();
                    // Isometric slope approximation
                    const slope = (y2_top - y1_top) / (x2 - x1);
                    const yStart = ly;
                    const yEnd = ly + (x2 - x1) * slope;

                    ctx.moveTo(x1, yStart);
                    ctx.lineTo(x2, yEnd);
                    ctx.lineTo(x2, yEnd + layerHeight);
                    ctx.lineTo(x1, yStart + layerHeight);
                    ctx.fill();
                }
            } 
            // Vertical Striations (Ice/Forest)
            else if (type === 'ICE' || type === 'FOREST') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.strokeStyle = (type === 'ICE') ? '#fff' : '#000';
                ctx.globalAlpha = (type === 'ICE') ? 0.3 : 0.15;
                ctx.lineWidth = 2;

                const steps = 6;
                const dx = (x2 - x1) / steps;
                const dy = (y2_top - y1_top) / steps;

                for(let k=1; k<steps; k++) {
                    const sx = x1 + k * dx;
                    const sy = y1_top + k * dy;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    ctx.lineTo(sx, sy + 300); // Straight down
                    ctx.stroke();
                }
            }
            ctx.restore();

            // Edge Definition (Anti-aliasing help)
            ctx.strokeStyle = 'rgba(0,0,0,0.2)'; 
            ctx.lineWidth = 0.5; 
            ctx.stroke();
        }

        // 2. Draw Top Face Background
        this.pathTop(ctx, cx, faceY);

        // Spotlight Gradient (Top-Left to Bottom-Right)
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.25)); 
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // --- PROCEDURAL TOP TEXTURE (The Juice) ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. High-Definition Bevels
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        this.pathTop(ctx, cx, cy);
        ctx.clip();

        if (type === 'FOREST') {
            // Stippling / Grass Tufts
            // Darker patches
            ctx.fillStyle = this.adjustBrightness(theme.top, 0.8);
            for(let i=0; i<15; i++) {
                const r = 4 + Math.random() * 6;
                const x = cx + (Math.random()-0.5) * HEX_SIZE * 1.5;
                const y = cy + (Math.random()-0.5) * HEX_SIZE * 1.0;
                ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI*2); ctx.fill();
            }
            // Grass blades
            ctx.strokeStyle = theme.detail; 
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.5;
            for(let k=0; k<40; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.7;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.2;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 2, ty - 3);
                ctx.stroke();
            }

        } else if (type === 'ICE') {
            // Crystalline Facets
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.2;

            for(let k=0; k<6; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.2;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*0.8;
                ctx.beginPath();
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + 15, ty + 5);
                ctx.lineTo(tx + 5, ty + 10);
                ctx.fill();
            }
            // Sharp scratches
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            for(let k=0; k<8; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.5;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE;
                const len = 10 + Math.random() * 10;
                ctx.moveTo(tx, ty);
                ctx.lineTo(tx + len, ty + len * 0.5);
            }
            ctx.stroke();

        } else if (type === 'MAGMA') {
            // Cooling Crust
            ctx.fillStyle = '#2a0a0a'; // Obsidian
            ctx.globalAlpha = 0.4;
            for(let k=0; k<12; k++) {
                const tx = cx + (Math.random()-0.5)*HEX_SIZE*1.6;
                const ty = cy + (Math.random()-0.5)*HEX_SIZE*1.0;
                const r = 5 + Math.random() * 8;
                ctx.beginPath(); 
                // Irregular polygon
                ctx.moveTo(tx+r, ty);
                ctx.lineTo(tx, ty+r);
                ctx.lineTo(tx-r, ty);
                ctx.lineTo(tx, ty-r);
                ctx.fill();
            }
            // Glowing Veins
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = '#f87171';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.6;
            ctx.beginPath();
            ctx.moveTo(cx-15, cy); ctx.lineTo(cx+15, cy+5);
            ctx.moveTo(cx, cy-10); ctx.lineTo(cx+5, cy+15);
            ctx.stroke();

        } else if (type === 'DESERT') {
            // Dunes / Ripples
            ctx.strokeStyle = this.adjustBrightness(theme.top, 0.85); // Darker sand
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4;

            for(let i=0; i<5; i++) {
                const offset = (i - 2) * 10;
                ctx.beginPath();
                // Sine wave curve
                for(let x = -20; x <= 20; x+=5) {
                    const y = Math.sin(x * 0.2) * 4;
                    if(x===-20) ctx.moveTo(cx + x + offset, cy + y + offset*0.5);
                    else ctx.lineTo(cx + x + offset, cy + y + offset*0.5);
                }
                ctx.stroke();
            }

        } else if (type === 'VOID') {
            // Hex Grid Overlay
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.3;

            const gridSize = 10;
            ctx.beginPath();
            // Isogrid
            for (let x = -HEX_SIZE; x < HEX_SIZE; x += gridSize) {
                ctx.moveTo(cx + x, cy - HEX_SIZE);
                ctx.lineTo(cx + x, cy + HEX_SIZE);
            }
            ctx.stroke();

            // Circuit Nodes
            ctx.fillStyle = theme.rim;
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.8;
            for(let k=0; k<4; k++) {
                const tx = cx + (Math.floor(Math.random()*4)-2) * gridSize;
                const ty = cy + (Math.floor(Math.random()*4)-2) * gridSize * 0.6;
                ctx.fillRect(tx-1, ty-1, 3, 3);
            }
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // 1. Inner Ambient Occlusion (Soft Shadow inside the hex)
        this.pathTop(ctx, cx, cy);
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 3;
        ctx.stroke();

        // 2. High-Contrast Rim Light (Top/Left edges)
        // This gives the "sharpness"
        ctx.beginPath();
        const c3 = HEX_CORNERS[3]; // Top Left
        const c4 = HEX_CORNERS[4]; // Top
        const c5 = HEX_CORNERS[5]; // Top Right
        const c0 = HEX_CORNERS[0]; // Right Connector

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c5.x, cy + c5.y);
        ctx.lineTo(cx + c4.x, cy + c4.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5; // Thinner but brighter
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.6)';
        ctx.stroke();

        // 3. Drop Shadow Rim (Bottom/Right edges)
        ctx.beginPath();
        const c1 = HEX_CORNERS[1]; // Bottom Right
        const c2 = HEX_CORNERS[2]; // Bottom Left

        ctx.moveTo(cx + c0.x, cy + c0.y);
        ctx.lineTo(cx + c1.x, cy + c1.y);
        ctx.lineTo(cx + c2.x, cy + c2.y);
        ctx.lineTo(cx + c3.x, cy + c3.y);

        ctx.strokeStyle = 'rgba(0,0,0,0.3)'; // Stronger dark line
        ctx.lineWidth = 1.0;
        ctx.stroke();
    }

    private pathTop(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }

    private adjustBrightness(hex: string, factor: number): string {
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

export const TerrainFactory = new TerrainCache();

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        // Standardized Dimensions for alignment
        // Renderer draws at (x - width/2), so cx must be exactly width/2.
        const width = 80;
        const height = 110;
        const { canvas, ctx } = createCanvas(width, height);

        const cx = 40; // Exact Center
        const cy = 95; // Ground Anchor Y (Matches GridSystem's OBSTACLE_ANCHOR_Y)

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // Common Shadow (Ground Ambient Occlusion)
        // Must be centered at cx, cy to ground the object
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.filter = 'blur(4px)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 24, 12, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';

        if (styleKey === 'TREE') {
            // --- STYLIZED PINE (Clean Geometric Layers) ---

            // Trunk
            ctx.fillStyle = '#291815'; // Darker Wood
            ctx.beginPath();
            ctx.moveTo(cx - 6, cy + 2); // Base slightly below pivot for grounding
            ctx.lineTo(cx + 6, cy + 2);
            ctx.lineTo(cx + 4, cy - 25);
            ctx.lineTo(cx - 4, cy - 25);
            ctx.fill();

            const layers = 3;
            const topY = cy - 95;
            const bottomY = cy - 20;

            for (let i = 0; i < layers; i++) {
                const ratio = i / layers;
                const layerY = topY + (bottomY - topY) * ratio;
                const spread = 15 + i * 14;

                const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
                grad.addColorStop(0, style.highlight); // Bright Tip
                grad.addColorStop(0.4, style.main); 
                grad.addColorStop(1, style.dark); // Dark Bottom

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18); // Tip
                // Left Flare
                ctx.quadraticCurveTo(cx - spread * 0.5, layerY + 5, cx - spread, layerY + 15);
                // Bottom Curve (Concave up)
                ctx.quadraticCurveTo(cx, layerY + 10, cx + spread, layerY + 15);
                // Right Flare
                ctx.quadraticCurveTo(cx + spread * 0.5, layerY + 5, cx, layerY - 18);
                ctx.fill();

                // Edge Highlight (Rim)
                ctx.strokeStyle = style.light;
                ctx.lineWidth = 1.5;
                ctx.lineCap = 'round';
                ctx.beginPath();
                ctx.moveTo(cx, layerY - 18);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.stroke();

                // Shadow underneath layer
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.beginPath();
                ctx.moveTo(cx, layerY + 10);
                ctx.lineTo(cx + spread, layerY + 15);
                ctx.lineTo(cx - spread, layerY + 15);
                ctx.fill();
            }

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- SHARP CRYSTAL CLUSTER ---

            const drawCrystal = (x: number, y: number, w: number, h: number, angle: number) => {
                ctx.save();
                ctx.translate(x, y);
                ctx.rotate(angle);

                // Facet 1 (Left/Dark)
                ctx.fillStyle = style.dark;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Facet 2 (Right/Light)
                const grad = ctx.createLinearGradient(0, -h, 0, 5);
                grad.addColorStop(0, '#ffffff');
                grad.addColorStop(0.3, style.light);
                grad.addColorStop(1, style.main);
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, 5); ctx.fill();

                // Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1.5;
                ctx.stroke();

                ctx.restore();
            };

            // Centered cluster
            drawCrystal(cx - 12, cy - 2, 8, 35, -0.25);
            drawCrystal(cx + 10, cy, 10, 30, 0.3);
            drawCrystal(cx, cy + 5, 14, 60, 0); // Main center shard

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MONOLITH (Dark Geometric) ---

            const topY = cy - 70;
            const w = 22;

            // Main Body Gradient
            const rockGrad = ctx.createLinearGradient(cx - w, topY, cx + w, cy);
            rockGrad.addColorStop(0, style.light);
            rockGrad.addColorStop(0.4, style.main);
            rockGrad.addColorStop(1, style.dark);
            ctx.fillStyle = rockGrad;

            ctx.beginPath();
            ctx.moveTo(cx, topY); // Top tip
            ctx.lineTo(cx + w, cy - 20); // Right mid
            ctx.lineTo(cx + 8, cy + 2); // Base Right (Grounded)
            ctx.lineTo(cx - 8, cy + 2); // Base Left
            ctx.lineTo(cx - w, cy - 20); // Left mid
            ctx.closePath();
            ctx.fill();

            // Facet Highlights (Edges)
            ctx.strokeStyle = style.light;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx - w, cy - 20);
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2); // Center spine
            ctx.stroke();

            // Emissive Veins
            ctx.strokeStyle = style.detail;
            ctx.shadowColor = style.highlight;
            ctx.shadowBlur = 8;
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(cx - 4, cy - 10); ctx.lineTo(cx + 4, cy - 30); ctx.lineTo(cx, cy - 50);
            ctx.stroke();
            ctx.shadowBlur = 0;

        } else if (styleKey === 'SANDSTONE') {
            // --- MESA STACK (Rounded Layers) ---

            const layers = 5;
            const w = 30;
            let currentW = w;
            let currentY = cy; // Start from ground

            for(let i=0; i<layers; i++) {
                const h = 12 + Math.random() * 4;
                const nextY = currentY - h;
                const nextW = currentW * (0.65 + Math.random() * 0.2); // Taper up

                // Gradient for rounded volume
                const grad = ctx.createLinearGradient(cx - currentW, 0, cx + currentW, 0);
                const color = i % 2 === 0 ? style.main : style.light;
                grad.addColorStop(0, style.dark);
                grad.addColorStop(0.2, color);
                grad.addColorStop(0.8, color);
                grad.addColorStop(1, style.dark);
                ctx.fillStyle = grad;

                // Base Oval
                ctx.beginPath();
                ctx.ellipse(cx, currentY, currentW, 8, 0, 0, Math.PI*2);
                ctx.fill();

                // Block body
                ctx.fillRect(cx - nextW, nextY, nextW * 2, currentY - nextY);

                // Top Highlight Rim
                ctx.strokeStyle = style.highlight;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.ellipse(cx, nextY, nextW, 6, 0, 0, Math.PI*2); ctx.stroke();
                ctx.globalAlpha = 1.0;

                currentY = nextY;
                currentW = nextW;
            }
            // Top Cap
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.ellipse(cx, currentY, currentW, 6, 0, 0, Math.PI*2);
            ctx.fill();

        } else {
            // --- WALL / STONE PILLAR ---
            const w = 28; // Half width
            const h = 55; // Height
            const topY = cy - h;

            // 1. Right Face (Shadow)
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8); // Isometric top-right
            ctx.lineTo(cx + w, cy - 8);   // Bottom-right
            ctx.lineTo(cx, cy + 2);            // Bottom-center
            ctx.fill();

            // 2. Left Face (Mid)
            ctx.fillStyle = style.main;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx - w, topY + 8);
            ctx.lineTo(cx - w, cy - 8);
            ctx.lineTo(cx, cy + 2);
            ctx.fill();

            // 3. Top Face (Light)
            ctx.fillStyle = style.light;
            ctx.beginPath();
            ctx.moveTo(cx, topY);
            ctx.lineTo(cx + w, topY + 8);
            ctx.lineTo(cx, topY + 16); // Center-down
            ctx.lineTo(cx - w, topY + 8);
            ctx.fill();

            // 4. Edges / Outline
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;

            ctx.beginPath();
            // Central Spine
            ctx.moveTo(cx, topY); ctx.lineTo(cx, cy + 2);
            // Top Diamond
            ctx.moveTo(cx, topY); ctx.lineTo(cx + w, topY + 8); ctx.lineTo(cx, topY + 16); ctx.lineTo(cx - w, topY + 8); ctx.lineTo(cx, topY);
            ctx.stroke();
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const width = 96;
        const height = 128;
        const { canvas, ctx } = createCanvas(width, height);
        const cx = 48;
        const cy = 108; // Ground anchor

        // Ice block uses ICE_CRYSTAL theme
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'] || { 
            main: '#7dd3fc', light: '#bae6fd', dark: '#0ea5e9', detail: '#e0f2fe', highlight: '#ffffff' 
        };

        const drawShard = (x: number, y: number, w: number, h: number, angle: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(angle);

            // Left Face
            ctx.fillStyle = style.dark;
            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(-w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Right Face
            const grad = ctx.createLinearGradient(0, -h, 0, w/2);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, style.light);
            grad.addColorStop(1, style.main);
            ctx.fillStyle = grad;

            ctx.beginPath(); ctx.moveTo(0, -h); ctx.lineTo(w, 0); ctx.lineTo(0, w/2); ctx.fill();

            // Highlights
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();
            ctx.restore();
        };

        // Ground ice
        ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.beginPath();
        ctx.ellipse(cx, cy, 30, 10, 0, 0, Math.PI*2);
        ctx.fill();

        // Cluster of ice shards
        drawShard(cx - 15, cy, 12, 50, -0.3);
        drawShard(cx + 15, cy - 5, 14, 45, 0.3);
        drawShard(cx, cy + 5, 20, 80, 0); // Main center shard

        return canvas;
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// --- GEOMETRY STANDARDIZATION ---
// Fixed Angle: Pointy Topped Hexagon (Starts at 30 degrees)
// This matches exactly with the selection ring math usually used in 2D grids.
const START_ANGLE = Math.PI / 6; 

const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}_V5_FIXED`; // V5: Geometry Fix & Seam Repair
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        // Base thickness helps ground the block visually
        const BASE_THICKNESS = 12; 
        const bottomPadding = hexVExtent + BASE_THICKNESS + 2; 
        const topPadding = hexVExtent + 2;

        const w = Math.ceil(HEX_SIZE * 2 + 4); // Tight width + padding
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot Point (Center of the Ground Plane)
        const cx = w / 2;
        const cy = h - bottomPadding; 

        // The Y position of the Top Face
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // Order: Back faces first (if we were drawing transparently), but for solids, 
        // we strictly draw the front 3 faces [0, 1, 2] in a loop or hardcoded.
        // For a pointy-topped hex, the visible sides are usually indices 0, 1, 2, 3... 
        // With PI/6 start, visible sides are roughly bottom-left, bottom, bottom-right.

        // Indices for visible front faces based on PI/6 start angle
        const visibleFaces = [0, 1, 2, 3]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            // Only draw if this face is actually "front facing" or "side facing"
            // With PI/6, c1.y and c2.y > 0 usually means front.
            // Let's rely on z-order: Draw sides first, then top covers them.

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Lighting logic based on face index
            let lightFactor = 0.8;
            if (i === 0) lightFactor = 0.9; // Front-Right
            if (i === 1) lightFactor = 0.6; // Bottom
            if (i === 2) lightFactor = 0.5; // Bottom-Left
            if (i === 3) lightFactor = 0.7; // Top-Left side (often hidden but needed for depth)

            // Skip back faces for optimization and cleanliness
            if (c1.y < -0.1 && c2.y < -0.1) continue; 

            // Side Gradient
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(theme.sideLight, lightFactor));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.4));

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_top);
            ctx.lineTo(x2, y2_top); 
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x1, y1_bottom);    
            ctx.closePath();
            ctx.fill();

            // Side Seam Fix: Stroke the shared edge to prevent background bleed
            ctx.strokeStyle = grad;
            ctx.lineWidth = 0.5;
            ctx.stroke();

            // --- PROCEDURAL SIDE DETAILS ---
            ctx.save();
            ctx.clip();
            if (type === 'MAGMA' || type === 'DESERT') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 0.2;
                for(let ly = faceY; ly < cy + BASE_THICKNESS; ly += 6) {
                    const slope = (y2_top - y1_top) / (x2 - x1);
                    const yStart = ly;
                    const yEnd = ly + (x2 - x1) * slope;
                    ctx.beginPath();
                    ctx.moveTo(x1, yStart); ctx.lineTo(x2, yEnd); 
                    ctx.lineTo(x2, yEnd+2); ctx.lineTo(x1, yStart+2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // 2. Draw Top Face
        // SEAM FIX: We draw the top face slightly larger or stroke it with the fill color
        // to cover the sub-pixel gap between top and sides.

        // Define Path
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(cx + c0.x, faceY + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(cx + c.x, faceY + c.y);
        }
        ctx.closePath();

        // Fill Logic
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.2)); 
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // *** THE FIX FOR "GLITCHES/TEARING" ***
        // Stroke the edge with the same color to seal pixels
        ctx.strokeStyle = topGrad;
        ctx.lineWidth = 1.0; 
        ctx.stroke();

        // --- PROCEDURAL TOP TEXTURE ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. Crisp Edges (Rim Light)
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        // Re-create clip path
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(cx + c0.x, cy + c0.y);
        for (let i = 1; i < 6; i++) { const c = HEX_CORNERS[i]; ctx.lineTo(cx + c.x, cy + c.y); }
        ctx.closePath();
        ctx.clip();

        // Reduce noise intensity for a cleaner look
        if (type === 'FOREST') {
            ctx.fillStyle = this.adjustBrightness(theme.top, 0.85);
            for(let i=0; i<20; i++) {
                const x = cx + (Math.random()-0.5) * HEX_SIZE * 1.8;
                const y = cy + (Math.random()-0.5) * HEX_SIZE * 1.8;
                ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'ICE') {
            ctx.strokeStyle = '#fff';
            ctx.globalAlpha = 0.3;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 15, cy - 10); ctx.lineTo(cx + 15, cy + 5);
            ctx.moveTo(cx + 10, cy - 15); ctx.lineTo(cx - 5, cy + 10);
            ctx.stroke();
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx-10, cy); ctx.lineTo(cx+5, cy+5); ctx.lineTo(cx+15, cy-5);
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // High Light (Top/Left edges)
        // With PI/6 start (Pointy top), top edges are indices 3, 4, 5
        const highlightIndices = [3, 4, 5];

        ctx.beginPath();
        for (let i = 0; i < highlightIndices.length; i++) {
            const idx = highlightIndices[i];
            const c1 = HEX_CORNERS[idx];
            const c2 = HEX_CORNERS[(idx + 1) % 6];

            if (i === 0) ctx.moveTo(cx + c1.x, cy + c1.y);
            else ctx.lineTo(cx + c1.x, cy + c1.y);
            ctx.lineTo(cx + c2.x, cy + c2.y);
        }

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5;
        // Brighter rim for "HD" feel
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.5)';
        ctx.stroke();

        // Shadow (Bottom edges)
        // Indices 0, 1, 2
        const shadowIndices = [0, 1, 2];
        ctx.beginPath();
        for (let i = 0; i < shadowIndices.length; i++) {
            const idx = shadowIndices[i];
            const c1 = HEX_CORNERS[idx];
            const c2 = HEX_CORNERS[(idx + 1) % 6];

            if (i === 0) ctx.moveTo(cx + c1.x, cy + c1.y);
            else ctx.lineTo(cx + c1.x, cy + c1.y);
            ctx.lineTo(cx + c2.x, cy + c2.y);
        }
        ctx.lineWidth = 1.0;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.stroke();
    }

    private adjustBrightness(hex: string, factor: number): string {
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

export const TerrainFactory = new TerrainCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// --- GEOMETRY STANDARDIZATION ---
// Must match TerrainFactory.ts exactly
const START_ANGLE = Math.PI / 6; 

const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Faces visible from isometric view (Front-Right, Front, Front-Left)
const VISIBLE_FACES = [0, 1, 2]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LAVA', color);
        const size = HEX_SIZE * 2.5; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        // --- CLIP MASK START ---
        // Constrain to hex shape before transforming for liquid effect
        this.pathHex(ctx, 0, 0);
        ctx.clip();
        // --- CLIP MASK END ---

        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate fluid motion via transforms
        // 1. Breathing Scale (Pulsing heat)
        const pulse = 1.0 + Math.sin(time * 2 + x * 0.1) * 0.05;
        // 2. Slow Rotation (Flow) - Randomized phase by X pos
        const rot = Math.sin(time * 0.5 + y * 0.1) * 0.1;

        ctx.rotate(rot);
        ctx.scale(pulse, pulse);

        ctx.globalAlpha = 0.9 * intensity;

        ctx.drawImage(texture, -half, -half, size, size);

        // Optional: Simple dynamic bubble (cheap)
        if (intensity > 0.8) {
            const bubbleX = Math.sin(time * 3 + x) * (HEX_SIZE * 0.4);
            const bubbleY = Math.cos(time * 2 + y) * (HEX_SIZE * 0.4);

            ctx.fillStyle = 'rgba(255,255,255,0.6)';
            ctx.beginPath(); 
            ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); 
            ctx.fill();
        }

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG (Poison, Smoke)
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;
        const halfSize = textureSize / 2;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        // Create cloud puffs
        const puffs = 4; // Reduced from 5
        for(let i=0; i<puffs; i++) {
            // Orbiting motion logic preserved
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5; // Scale relative to texture size
            const size = textureSize * scale;

            // Draw Cached Texture
            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        // Ground Haze (Base layer) using same texture stretched
        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS (Smash, Earthquake)
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        // --- CLIP MASK START ---
        this.pathHex(ctx, 0, 0);
        ctx.clip();
        // --- CLIP MASK END ---

        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        // Slight rotation for variety based on position (pseudo-random)
        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex (Kept for basic fields/walls/indicators)
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            // NOTE: Gradient here is still needed for depth, but it's only 3 per hex
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        // Optimized Seed: Use bitwise ops for speed
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                // Using the optimized drawGroundCracks which now uses cache
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            // VOID texture logic remains simple rects, but use context save/restore carefully
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LAVA' | 'FILL' | 'RING' | 'DASHED', color: string): HTMLCanvasElement {
        const key = `${type}_${color}_V3_ALIGNED`; // Version bumped for alignment fix
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'FILL') {
            // Pure fill, no stroke
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.95);
            ctx.fill();
        }
        else if (type === 'RING') {
            // Pure stroke, no glow
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'DASHED') {
            // Dashed stroke
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 8]);
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LAVA') {
            // High-Performance Baked Liquid
            // 1. Fluid Body
            ctx.fillStyle = color;
            // Use a slightly irregular shape for base
            ctx.beginPath();
            for(let i=0; i<=12; i++) {
                const a = (i/12) * Math.PI * 2;
                // Static noise for shape
                const noise = Math.sin(a * 3) * 5; 
                const rad = r * 0.9 + noise;
                const x = Math.cos(a) * rad;
                const y = Math.sin(a) * rad;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // 2. Inner Depth (Crust/Darker Pool)
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = color; 
            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.65, 0, Math.PI * 2); 
            ctx.fill();

            // 3. Specular Highlights (Gloss)
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            ctx.beginPath();
            ctx.ellipse(0, -r * 0.55, r * 0.4, 6, 0, 0, Math.PI*2);
            ctx.fill();

            // 4. Baked Bubbles (Static)
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(r*0.3, r*0.3, r*0.08, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-r*0.25, -r*0.15, r*0.05, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        // --- FIXED GEOMETRY (PI/6 Start) ---
        const startAngle = Math.PI / 6;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r; // No Scale Y here (baked square, scaled at draw)
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// --- GEOMETRY STANDARDIZATION ---
// Fixed Angle: Pointy Topped Hexagon (Starts at 30 degrees)
// This matches exactly with the selection ring math usually used in 2D grids.
const START_ANGLE = Math.PI / 6; 

const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

class TerrainCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getBlock(theme: any, type: string, tier: number): HTMLCanvasElement {
        const key = `${type}_T${tier}_V5_FIXED`; // V5: Geometry Fix & Seam Repair
        if (this.cache.has(key)) return this.cache.get(key)!;

        const canvas = this.bakeBlock(theme, tier, type);
        this.cache.set(key, canvas);
        return canvas;
    }

    public getGroundAnchorY(canvasHeight: number, bottomPadding: number): number {
        return canvasHeight - bottomPadding;
    }

    private bakeBlock(theme: any, tier: number, type: string): HTMLCanvasElement {
        const hOffset = tier * BLOCK_HEIGHT; 

        // --- METRICS ---
        const hexVExtent = Math.ceil(HEX_SIZE * ISO_SCALE_Y);
        // Base thickness helps ground the block visually
        const BASE_THICKNESS = 12; 
        const bottomPadding = hexVExtent + BASE_THICKNESS + 2; 
        const topPadding = hexVExtent + 2;

        const w = Math.ceil(HEX_SIZE * 2 + 4); // Tight width + padding
        const h = Math.ceil(topPadding + Math.max(0, hOffset) + bottomPadding);

        const { canvas, ctx } = createCanvas(w, h);

        // Pivot Point (Center of the Ground Plane)
        const cx = w / 2;
        const cy = h - bottomPadding; 

        // The Y position of the Top Face
        const faceY = cy - hOffset;

        // 1. Draw Side Faces (Prism Body)
        // With PI/6 start (Pointy top), visible sides from "South" view are 0, 1, 2, 5
        // Indices: 0(Bottom-Right), 1(Bottom), 2(Bottom-Left), 3(Top-Left), 4(Top), 5(Top-Right)
        // We draw front-facing sides: 0, 1, 2. (and maybe 5 depending on perspective, but 0-1-2 is main bulk)
        const visibleFaces = [0, 1, 2, 5]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            // Skip back faces (Top-Left and Top)
            // c1.y and c2.y being negative usually implies back face in screen space relative to center
            if (c1.y < -0.1 && c2.y < -0.1) continue; 

            const x1 = cx + c1.x;
            const y1_top = faceY + c1.y;
            const x2 = cx + c2.x;
            const y2_top = faceY + c2.y;

            const y1_bottom = cy + c1.y + BASE_THICKNESS;
            const y2_bottom = cy + c2.y + BASE_THICKNESS;

            // Lighting logic based on face index
            let lightFactor = 0.8;
            if (i === 0) lightFactor = 0.6; // Bottom-Right (Shadow side)
            if (i === 1) lightFactor = 0.8; // Bottom (Mid)
            if (i === 2) lightFactor = 1.0; // Bottom-Left (Lit side)
            if (i === 5) lightFactor = 0.5; // Top-Right (Darkest)

            // Side Gradient
            const grad = ctx.createLinearGradient(0, faceY, 0, cy + BASE_THICKNESS);
            grad.addColorStop(0, this.adjustBrightness(theme.sideLight, lightFactor));
            grad.addColorStop(1, this.adjustBrightness(theme.sideDark, 0.4));

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_top);
            ctx.lineTo(x2, y2_top); 
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x1, y1_bottom);    
            ctx.closePath();
            ctx.fill();

            // Side Seam Fix: Stroke the shared edge to prevent background bleed
            ctx.strokeStyle = grad;
            ctx.lineWidth = 0.5;
            ctx.stroke();

            // --- PROCEDURAL SIDE DETAILS ---
            ctx.save();
            ctx.clip();
            if (type === 'MAGMA' || type === 'DESERT') {
                ctx.globalCompositeOperation = 'overlay';
                ctx.fillStyle = '#000';
                ctx.globalAlpha = 0.2;
                for(let ly = faceY; ly < cy + BASE_THICKNESS; ly += 6) {
                    const slope = (y2_top - y1_top) / (x2 - x1);
                    const yStart = ly;
                    const yEnd = ly + (x2 - x1) * slope;
                    ctx.beginPath();
                    ctx.moveTo(x1, yStart); ctx.lineTo(x2, yEnd); 
                    ctx.lineTo(x2, yEnd+2); ctx.lineTo(x1, yStart+2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // 2. Draw Top Face
        // Define Path
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(cx + c0.x, faceY + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(cx + c.x, faceY + c.y);
        }
        ctx.closePath();

        // Fill Logic
        const topGrad = ctx.createLinearGradient(cx - HEX_SIZE, faceY - HEX_SIZE, cx + HEX_SIZE, faceY + HEX_SIZE);
        topGrad.addColorStop(0, this.adjustBrightness(theme.top, 1.2)); 
        topGrad.addColorStop(1, theme.top); 
        ctx.fillStyle = topGrad;
        ctx.fill();

        // *** THE FIX FOR "TEARING" ***
        // Stroke the edge with the same color to seal sub-pixel gaps between top and sides
        ctx.strokeStyle = topGrad;
        ctx.lineWidth = 1.0; 
        ctx.stroke();

        // --- PROCEDURAL TOP TEXTURE ---
        this.drawTopTexture(ctx, cx, faceY, type, theme);

        // 3. Crisp Edges (Rim Light)
        this.drawBevels(ctx, cx, faceY, theme);

        // Metadata
        (canvas as any).bottomPadding = bottomPadding;

        return canvas;
    }

    private drawTopTexture(ctx: CanvasRenderingContext2D, cx: number, cy: number, type: string, theme: any) {
        ctx.save();
        // Re-create clip path
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(cx + c0.x, cy + c0.y);
        for (let i = 1; i < 6; i++) { const c = HEX_CORNERS[i]; ctx.lineTo(cx + c.x, cy + c.y); }
        ctx.closePath();
        ctx.clip();

        // Reduce noise intensity for a cleaner look
        if (type === 'FOREST') {
            ctx.fillStyle = this.adjustBrightness(theme.top, 0.85);
            for(let i=0; i<20; i++) {
                const x = cx + (Math.random()-0.5) * HEX_SIZE * 1.8;
                const y = cy + (Math.random()-0.5) * HEX_SIZE * 1.8;
                ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'ICE') {
            ctx.strokeStyle = '#fff';
            ctx.globalAlpha = 0.3;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - 15, cy - 10); ctx.lineTo(cx + 15, cy + 5);
            ctx.moveTo(cx + 10, cy - 15); ctx.lineTo(cx - 5, cy + 10);
            ctx.stroke();
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx-10, cy); ctx.lineTo(cx+5, cy+5); ctx.lineTo(cx+15, cy-5);
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawBevels(ctx: CanvasRenderingContext2D, cx: number, cy: number, theme: any) {
        // High Light (Top/Left edges)
        // With PI/6 start (Pointy top), top edges are indices 3, 4, 5
        const highlightIndices = [3, 4, 5];

        ctx.beginPath();
        for (let i = 0; i < highlightIndices.length; i++) {
            const idx = highlightIndices[i];
            const c1 = HEX_CORNERS[idx];
            const c2 = HEX_CORNERS[(idx + 1) % 6];

            if (i === 0) ctx.moveTo(cx + c1.x, cy + c1.y);
            else ctx.lineTo(cx + c1.x, cy + c1.y);
            ctx.lineTo(cx + c2.x, cy + c2.y);
        }

        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.lineWidth = 1.5;
        // Brighter rim for "HD" feel
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.5)';
        ctx.stroke();

        // Shadow (Bottom edges)
        // Indices 0, 1, 2
        const shadowIndices = [0, 1, 2];
        ctx.beginPath();
        for (let i = 0; i < shadowIndices.length; i++) {
            const idx = shadowIndices[i];
            const c1 = HEX_CORNERS[idx];
            const c2 = HEX_CORNERS[(idx + 1) % 6];

            if (i === 0) ctx.moveTo(cx + c1.x, cy + c1.y);
            else ctx.lineTo(cx + c1.x, cy + c1.y);
            ctx.lineTo(cx + c2.x, cy + c2.y);
        }
        ctx.lineWidth = 1.0;
        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
        ctx.stroke();
    }

    private adjustBrightness(hex: string, factor: number): string {
        let r = parseInt(hex.substring(1, 3), 16);
        let g = parseInt(hex.substring(3, 5), 16);
        let b = parseInt(hex.substring(5, 7), 16);

        r = Math.min(255, Math.floor(r * factor));
        g = Math.min(255, Math.floor(g * factor));
        b = Math.min(255, Math.floor(b * factor));

        const toHex = (c: number) => {
            const hex = c.toString(16);
            return hex.length === 1 ? "0" + hex : hex;
        };

        return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
    }
}

export const TerrainFactory = new TerrainCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// --- GEOMETRY STANDARDIZATION ---
// Must match TerrainFactory.ts exactly
const START_ANGLE = Math.PI / 6; 

const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Faces visible from isometric view
const VISIBLE_FACES = [0, 1, 2]; 

export const SurfaceAssets = {

    pathHex(ctx: CanvasRenderingContext2D, x: number, y: number, scale: number = 1.0) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const c = HEX_CORNERS[i];
            if (i === 0) ctx.moveTo(x + c.x * scale, y + c.y * scale);
            else ctx.lineTo(x + c.x * scale, y + c.y * scale);
        }
        ctx.closePath();
    },

    // 1. LIQUID SURFACE (Blood, Lava, Acid)
    drawLiquidSurface(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        const texture = VFXFactory.getTexture('LAVA', color);
        const size = HEX_SIZE * 2.5; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        // --- CLIP MASK START ---
        // Constrain to hex shape before transforming for liquid effect
        this.pathHex(ctx, 0, 0);
        ctx.clip();
        // --- CLIP MASK END ---

        ctx.scale(1, ISO_SCALE_Y); 

        // Simulate fluid motion via transforms
        const pulse = 1.0 + Math.sin(time * 2 + x * 0.1) * 0.05;
        const rot = Math.sin(time * 0.5 + y * 0.1) * 0.1;

        ctx.rotate(rot);
        ctx.scale(pulse, pulse);

        ctx.globalAlpha = 0.9 * intensity;

        ctx.drawImage(texture, -half, -half, size, size);

        if (intensity > 0.8) {
            const bubbleX = Math.sin(time * 3 + x) * (HEX_SIZE * 0.4);
            const bubbleY = Math.cos(time * 2 + y) * (HEX_SIZE * 0.4);

            ctx.fillStyle = 'rgba(255,255,255,0.6)';
            ctx.beginPath(); 
            ctx.arc(bubbleX, bubbleY, 3, 0, Math.PI*2); 
            ctx.fill();
        }

        ctx.restore();
    },

    // 2. VOLUMETRIC FOG
    drawVolumetricFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const puffTexture = VFXFactory.getTexture('GLOW', color);
        const textureSize = puffTexture.width;

        ctx.save();
        ctx.translate(x, y);

        ctx.globalCompositeOperation = 'screen'; 
        ctx.globalAlpha = 0.2; 

        const puffs = 4;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.5 + i * (Math.PI * 2 / puffs);
            const dist = Math.sin(time * 0.2 + i) * 15;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist * ISO_SCALE_Y - 15; 

            const scale = (1.0 + Math.sin(time + i) * 0.2) * 0.5;
            const size = textureSize * scale;

            ctx.drawImage(puffTexture, px - size/2, py - size/2, size, size);
        }

        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalAlpha = 0.15;
        const baseSize = HEX_SIZE * 2.5;
        ctx.drawImage(puffTexture, -baseSize/2, -baseSize/2, baseSize, baseSize);

        ctx.restore();
    },

    // 3. GROUND CRACKS
    drawGroundCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 
        const half = size / 2;

        ctx.save();
        ctx.translate(x, y);

        this.pathHex(ctx, 0, 0);
        ctx.clip();

        ctx.scale(1, ISO_SCALE_Y);
        ctx.globalCompositeOperation = 'lighter'; 
        ctx.globalAlpha = intensity;

        const staticRot = (x % 3) * (Math.PI / 3);
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -half, -half, size, size);

        ctx.restore();
    },

    // Original Extruded Hex
    drawExtrudedHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number,
        isHollow: boolean = false
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity * 0.6;

        for (const i of VISIBLE_FACES) {
            const idx1 = i;
            const idx2 = (i + 1) % 6;

            const c1 = HEX_CORNERS[idx1];
            const c2 = HEX_CORNERS[idx2];

            let shade = 1.0;
            if (i === 5) shade = 0.7; 
            if (i === 0) shade = 0.5; 
            if (i === 1) shade = 0.9; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c2.x, topY + c2.y);
            ctx.lineTo(x + c2.x, bottomY + c2.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.closePath();

            const oldAlpha = ctx.globalAlpha;
            ctx.globalAlpha = oldAlpha * shade;
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.8;
            ctx.beginPath();
            ctx.moveTo(x + c1.x, topY + c1.y);
            ctx.lineTo(x + c1.x, bottomY + c1.y);
            ctx.stroke();

            ctx.globalAlpha = oldAlpha;
        }

        if (!isHollow) {
            ctx.globalAlpha = opacity;
            ctx.fillStyle = color;
            this.pathHex(ctx, x, topY, 1.0);
            ctx.fill();

            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = opacity * 0.5;
            this.pathHex(ctx, x, topY, 0.8);
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        this.pathHex(ctx, x, topY, 1.0);
        ctx.stroke();

        ctx.restore();
    },

    drawTexture(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        color: string,
        globalTime: number
    ) {
        const seed = ((q * 73856093) ^ (r * 19349663)) / 2147483647; 
        const normalizedSeed = Math.abs(seed - Math.floor(seed));

        if (type === 'MAGMA') {
            if (normalizedSeed > 0.5) {
                this.drawGroundCracks(ctx, cx, cy, '#ef4444', 0.6);
            }
        } else if (type === 'VOID') {
            if (normalizedSeed > 0.7) {
                ctx.save();
                ctx.fillStyle = '#38bdf8';
                ctx.globalAlpha = 0.4;
                ctx.fillRect(cx - 2, cy - 2, 4, 4);

                ctx.strokeStyle = color;
                ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+10, cy-5); ctx.stroke();
                ctx.restore();
            }
        }
    },

    drawUnitRune(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        color: string, 
        t: number, 
        progress: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 
        const r = HEX_SIZE * 0.8 * progress; 
        ctx.globalAlpha = 0.8;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.stroke();
        ctx.rotate(t * 2);
        ctx.lineWidth = 4;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI/4); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, r, Math.PI, Math.PI + Math.PI/4); ctx.stroke();
        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { isChaosStyle } from "../systems/vfx/utils";

// Dimensions
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: 'GLOW' | 'SOLID' | 'OUTLINE' | 'NOISE' | 'BLAST' | 'SHARD' | 'CHIP' | 'CRACKS' | 'LAVA' | 'FILL' | 'RING' | 'DASHED', color: string): HTMLCanvasElement {
        const key = `${type}_${color}_V3_ALIGNED`; // Version bumped for alignment fix
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        if (type === 'GLOW') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
            grad.addColorStop(0, '#ffffff');
            grad.addColorStop(0.2, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            this.pathHex(ctx, r);
            ctx.fill();
        } 
        else if (type === 'SOLID') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.9);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 2;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'FILL') {
            // Pure fill, no stroke
            ctx.fillStyle = color;
            this.pathHex(ctx, r * 0.95);
            ctx.fill();
        }
        else if (type === 'RING') {
            // Pure stroke, no glow
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'DASHED') {
            // Dashed stroke
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.setLineDash([10, 8]);
            this.pathHex(ctx, r * 0.9);
            ctx.stroke();
        }
        else if (type === 'OUTLINE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.pathHex(ctx, r * 0.8);
            ctx.stroke();
        }
        else if (type === 'NOISE') {
            ctx.fillStyle = color;
            this.pathHex(ctx, r);
            ctx.fill();
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            for(let i=0; i<20; i++) {
                const rx = (Math.random() - 0.5) * r * 1.5;
                const ry = (Math.random() - 0.5) * r * 1.5;
                const rs = Math.random() * r * 0.4;
                ctx.beginPath(); ctx.arc(rx, ry, rs, 0, Math.PI*2); ctx.fill();
            }
        }
        else if (type === 'BLAST') {
            const isChaos = isChaosStyle(color);
            if (isChaos) {
                ctx.fillStyle = color;
                ctx.beginPath();
                for(let i=0; i<12; i++) {
                    const angle = (i / 12) * Math.PI * 2;
                    const rad = (i % 2 === 0) ? r : r * 0.4;
                    const x = Math.cos(angle) * rad;
                    const y = Math.sin(angle) * rad;
                    if(i===0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                }
                ctx.closePath();
                ctx.fill();
            } else {
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#ffffff');        
                grad.addColorStop(0.3, color);          
                grad.addColorStop(1, 'transparent');  
                ctx.fillStyle = grad;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            }
        }
        else if (type === 'CHIP') {
            // Simple Square Chip
            ctx.fillStyle = color;
            ctx.fillRect(-r/2, -r/2, r, r);
        }
        else if (type === 'SHARD') {
            // Triangular Shard
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(r, 0);
            ctx.lineTo(-r * 0.5, r * 0.4);
            ctx.lineTo(-r * 0.5, -r * 0.4);
            ctx.fill();
            // Subtle highlight
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 4;
            ctx.stroke();
        }
        else if (type === 'CRACKS') {
            // Pre-baked jagged fractal lines for Magma/Ground effects
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.lineCap = 'round';

            const branches = 4;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2 + (Math.random()*0.5);
                ctx.beginPath();
                ctx.moveTo(0, 0);

                let cx = 0, cy = 0;
                const len = r * 0.9;
                const steps = 3;
                for(let j=0; j<steps; j++) {
                    const stepLen = len / steps;
                    const r1 = Math.sin(i * 99 + j * 33);
                    const r2 = Math.cos(i * 55 + j * 77);

                    cx += Math.cos(angle) * stepLen + r1 * 8;
                    cy += Math.sin(angle) * stepLen + r2 * 8;
                    ctx.lineTo(cx, cy);
                }
                ctx.stroke();
            }
            // Glowing Core
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();
        }
        else if (type === 'LAVA') {
            // High-Performance Baked Liquid
            // 1. Fluid Body
            ctx.fillStyle = color;
            // Use a slightly irregular shape for base
            ctx.beginPath();
            for(let i=0; i<=12; i++) {
                const a = (i/12) * Math.PI * 2;
                // Static noise for shape
                const noise = Math.sin(a * 3) * 5; 
                const rad = r * 0.9 + noise;
                const x = Math.cos(a) * rad;
                const y = Math.sin(a) * rad;
                if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
            ctx.fill();

            // 2. Inner Depth (Crust/Darker Pool)
            ctx.globalCompositeOperation = 'multiply';
            ctx.fillStyle = color; 
            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.65, 0, Math.PI * 2); 
            ctx.fill();

            // 3. Specular Highlights (Gloss)
            ctx.globalCompositeOperation = 'screen';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
            ctx.beginPath();
            ctx.ellipse(0, -r * 0.55, r * 0.4, 6, 0, 0, Math.PI*2);
            ctx.fill();

            // 4. Baked Bubbles (Static)
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.7;
            ctx.beginPath(); ctx.arc(r*0.3, r*0.3, r*0.08, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(-r*0.25, -r*0.15, r*0.05, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    private pathHex(ctx: CanvasRenderingContext2D, r: number) {
        // --- FIXED GEOMETRY (PI/6 Start) ---
        const startAngle = Math.PI / 6;
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = startAngle + i * Math.PI / 3;
            const x = Math.cos(angle) * r;
            const y = Math.sin(angle) * r; // No Scale Y here (baked square, scaled at draw)
            if (i === 0) ctx.moveTo(x, y);
            else ctx.lineTo(x, y);
        }
        ctx.closePath();
    }

    generateGlowOrb(color: string, size: number = 64): HTMLCanvasElement {
        return this.getTexture('GLOW', color);
    }

    generateFogCloud(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW', color); 
    }

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        return this.createLegacyProjectile(visual, color);
    }

    generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('BLAST', color);
    }

    generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    private createLegacyProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 64);
        const cx = 48, cy = 32;
        ctx.shadowColor = color; ctx.shadowBlur = 10;
        ctx.lineCap = 'round'; ctx.lineJoin = 'round';

        if (visual === 'ARROW') {
            ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(10, cy); ctx.lineTo(80, cy); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.moveTo(90, cy); ctx.lineTo(70, cy - 8); ctx.lineTo(75, cy); ctx.lineTo(70, cy + 8); ctx.fill();
        } else {
            const grad = ctx.createLinearGradient(0, 0, 96, 0);
            grad.addColorStop(0, 'transparent'); grad.addColorStop(0.5, color); grad.addColorStop(1, '#fff');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.ellipse(cx, cy, 30, 8, 0, 0, Math.PI*2); ctx.fill();
        }
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();
